"""Edit vocabulary for the pool-break scene.

The three causal controls the scene was built to demonstrate: how hard the cue
ball is struck, where on the apex ball it lands, and how heavy the cue ball is.
Kept separate from the simulation so PCVE-style edit prompts stay data-driven --
the same three names appear in the DSL, in the prompts JSON and in the physics
dict the simulator reads.

Why the contact point is a signed distance and not an angle
-----------------------------------------------------------
"Hit it a bit to the left" is an impact parameter: the perpendicular distance
between the cue ball's line of travel and the apex ball's centre. Expressed as
an aim *angle* the same shot is 1.4 degrees, which is both useless as a prompt
("increase the angle by a little") and wrong as a knob -- the cue starts a metre
away, so a 1.4 degree aim error moves the impact point by a full ball radius.
Metres are what the physics actually uses, so metres are what the vocabulary
says. Positive is the apex ball's right side, i.e. the right of the frame in the
default camera; +/- one ball radius (0.0286 m) is a half-ball hit.
"""

from __future__ import annotations

# Locate reference common scripts and install this scene's embedded helpers.
import sys as _bundle_sys0
from pathlib import Path as _BundlePath0
_BUNDLE_SCENE = _BundlePath0(__file__).resolve().parent
_BUNDLE_SCRIPTS = _BUNDLE_SCENE.parent
_PCVE_PROJECT_ROOT = next(p for p in _BUNDLE_SCENE.parents if (p / "assets").is_dir())
if str(_BUNDLE_SCRIPTS) not in _bundle_sys0.path:
    _bundle_sys0.path.insert(0, str(_BUNDLE_SCRIPTS))

# Scene-local source bundle: installed before importing scene support modules.
import importlib.abc as _bundle_abc
import importlib.util as _bundle_util
import json as _bundle_json
import sys as _bundle_sys
from pathlib import Path as _BundlePath

_BUNDLE_SCENE = _BundlePath(__file__).resolve().parent
_BUNDLE_SCRIPTS = _BUNDLE_SCENE.parent
_BUNDLE_PROJECT = next(p for p in _BUNDLE_SCENE.parents if (p / "assets").is_dir())
if str(_BUNDLE_SCRIPTS) not in _bundle_sys.path:
    _bundle_sys.path.insert(0, str(_BUNDLE_SCRIPTS))

_BUNDLE_SOURCES = _bundle_json.loads(r"""{"pcve_project_paths": "\"\"\"Path helpers shared by standalone rigid-scene folders.\"\"\"\nfrom pathlib import Path\nimport sys\n\n\ndef project_root(anchor):\n    anchor = Path(anchor).resolve()\n    candidates = (anchor, *anchor.parents)\n    for candidate in candidates:\n        if (candidate / \"assets\").is_dir() and (candidate / \"clean_scripts\").is_dir():\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate project root above {anchor}; expected assets/ and clean_scripts/\")\n\n\ndef scene_root(anchor):\n    \"\"\"Find the scene folder from argv first, then from the helper's parents.\"\"\"\n    candidates = []\n    if sys.argv and sys.argv[0] not in {\"-\", \"\"}:\n        argv_path = Path(sys.argv[0]).expanduser()\n        if not argv_path.is_absolute():\n            argv_path = Path.cwd() / argv_path\n        candidates.append(argv_path.resolve().parent)\n    anchor = Path(anchor).resolve()\n    candidates.extend(anchor.parents)\n    seen = set()\n    for candidate in candidates:\n        if candidate in seen:\n            continue\n        seen.add(candidate)\n        if any(candidate.glob(\"simulate_*.py\")) and any(candidate.glob(\"render_*.py\")):\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate scene entrypoints above {anchor}\")\n", "pcve_scene_runtime": "\"\"\"Shared command-line and output contracts for PCVE scene entry points.\n\nBoth ``blender -b --python render.py -- ...`` and Python with bpy are supported.\nThis module has no Blender dependency until a renderer finishes.\n\"\"\"\n\nimport argparse\nimport hashlib\nimport json\nimport math\nimport os\nimport random\nimport shutil\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n_render_args = None\n\n\ndef python_for(role: str) -> Path:\n    override = os.environ.get(\"PCVE_PHYSICS_PYTHON\" if role == \"physics\" else \"PCVE_RENDER_PYTHON\")\n    if override:\n        return Path(override).expanduser()\n    names = (\"sim/python.exe\", \"sim/bin/python\") if role == \"physics\" else (\n        \"render/Scripts/python.exe\", \"render/bin/python\")\n    for base in (ROOT / \".runtime\", ROOT.parent / \"PCVE-ElasticBench/.runtime\"):\n        for name in names:\n            if (base / name).is_file():\n                return base / name\n    if role == \"physics\":\n        # The original Linux setup activates a PyBullet conda environment and\n        # invokes Blender separately. Blender's sys.executable is not Python.\n        candidates = [ROOT.parent / \"miniconda/envs/physics/bin/python\"]\n        if os.environ.get(\"CONDA_PREFIX\"):\n            prefix = Path(os.environ[\"CONDA_PREFIX\"])\n            candidates += [prefix / \"python.exe\", prefix / \"bin/python\"]\n        for name in (\"python3\", \"python\"):\n            if shutil.which(name):\n                candidates.append(Path(shutil.which(name)))\n        for candidate in candidates:\n            if candidate.is_file() and \"blender\" not in candidate.name.lower():\n                return candidate\n    return Path(sys.executable)\n\n\ndef _add(parser, flag, **kwargs):\n    if flag not in parser._option_string_actions:\n        parser.add_argument(flag, **kwargs)\n\n\ndef implementation_hashes(directory):\n    files = list(Path(directory).glob(\"*.py\"))\n    files += [ROOT / \"clean_scripts\" / name for name in (\"pcve_scene_pipeline.py\", \"pcve_edit_dsl.py\")]\n    return {str(path.relative_to(ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n            for path in files if path.is_file()}\n\n\ndef case_outputs(folder):\n    \"\"\"Semantic output keys used by the original suite manifests.\"\"\"\n    names = dict(video=\"video.mp4\", ground_truth=\"ground_truth_transforms.json\",\n                 scenario_metadata=\"scenario_metadata.json\", scenario_overrides=\"scenario_overrides.json\",\n                 physics=\"physics_transforms.json\", scenario_input=\"scenario_input.json\", preview=\"preview.png\")\n    return {key: str((Path(folder) / name).resolve()) for key, name in names.items()\n            if (Path(folder) / name).is_file()}\n\n\ndef add_build_arguments(parser):\n    _add(parser, \"--blender\", type=Path, help=\"Blender executable; otherwise use render Python with bpy.\")\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    _add(parser, \"--render-python\", type=Path, default=python_for(\"render\"))\n    _add(parser, \"--engine\", choices=(\"cycles\", \"eevee\"), default=\"cycles\")\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    return parser\n\n\ndef render_prefix(args, script: Path) -> list[str]:\n    blender = getattr(args, \"blender\", None) or os.environ.get(\"BLENDER_BIN\")\n    render_python = Path(getattr(args, \"render_python\", python_for(\"render\")))\n    if not blender and render_python == Path(sys.executable):\n        candidates = [ROOT / \"tools/blender-3.6.23-linux-x64/blender\"]\n        if shutil.which(\"blender\"):\n            candidates.append(Path(shutil.which(\"blender\")))\n        blender = next((path for path in candidates if path.is_file()), None)\n    if blender:\n        # Blender otherwise returns success even when the Python script raises.\n        return [str(Path(blender).expanduser()), \"-b\", \"--python-exit-code\", \"1\",\n                \"--python\", str(script), \"--\"]\n    return [str(render_python), str(script)]\n\n\ndef append_render_options(command, args):\n    for name in (\"engine\", \"device\", \"preview_frame\"):\n        flag = \"--\" + name.replace(\"_\", \"-\")\n        value = getattr(args, name, None)\n        if value is not None and flag not in command:\n            command += [flag, str(value)]\n    return command\n\n\ndef parse_render_args(parser, argv=None):\n    global _render_args\n    _add(parser, \"--seed\", type=int, default=0)\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    # Renderers without an engine switch currently implement Cycles only.\n    _add(parser, \"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    if argv is None:\n        argv = sys.argv[sys.argv.index(\"--\") + 1:] if \"--\" in sys.argv else sys.argv[1:]\n    _render_args = parser.parse_args(argv)\n    # In the original CLI duration-sec is the real-time clip length. A scene's\n    # optional demo slow-motion preset must not silently multiply that request.\n    if \"--duration-sec\" in argv and \"--slow-motion\" not in argv and hasattr(_render_args, \"slow_motion\"):\n        _render_args.slow_motion = 1\n    random.seed(_render_args.seed)\n    return _render_args\n\n\ndef apply_physics_overrides(args, baseline):\n    \"\"\"Read the original {physics: ...} override format for scalar CLI scenes.\n\n    Bare schedule arrays remain accepted by the older timed-edit escape hatch.\n    Explicit scalar command-line values take precedence over the JSON defaults.\n    \"\"\"\n    path = getattr(args, \"scenario_overrides_json\", None)\n    if path is None:\n        return None\n    payload = json.loads(Path(path).read_text(encoding=\"utf-8\"))\n    if isinstance(payload, list):\n        return Path(path)\n    physics = payload.get(\"physics\", payload)\n    unknown = set(physics) - {*baseline, \"timed_edits\"}\n    if unknown:\n        raise ValueError(f\"Unknown physics overrides: {sorted(unknown)}\")\n    for name, value in physics.items():\n        if name != \"timed_edits\" and getattr(args, name, None) is None:\n            setattr(args, name, value)\n    if physics.get(\"timed_edits\"):\n        target = Path(args.out_dir) / \"timed_edits.json\"\n        target.parent.mkdir(parents=True, exist_ok=True)\n        target.write_text(json.dumps(physics[\"timed_edits\"], indent=2), encoding=\"utf-8\")\n        return target\n    return None\n\n\ndef _matrix(position, q):\n    x, y, z, w = q\n    return [[1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w), position[0]],\n            [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w), position[1]],\n            [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y), position[2]],\n            [0, 0, 0, 1]]\n\n\ndef _optional_metrics(value):\n    if isinstance(value, dict):\n        return {key: _optional_metrics(item) for key, item in value.items()}\n    if isinstance(value, list):\n        return [_optional_metrics(item) for item in value]\n    if isinstance(value, float) and not math.isfinite(value):\n        return None\n    return value\n\n\ndef finalize_render_outputs(out: Path, scene_name: str, args, scene=None):\n    \"\"\"Keep scene-specific files and also publish the original PCVE filenames.\"\"\"\n    out = Path(out).resolve()\n    gt_path = out / \"ground_truth_transforms.json\"\n    if gt_path.is_file():\n        gt = json.loads(gt_path.read_text(encoding=\"utf-8\"))\n        gt.setdefault(\"scene\", scene_name)\n        gt.setdefault(\"schema_version\", 1)\n        camera = gt.setdefault(\"camera\", {})\n        camera.setdefault(\"resolution\", list(args.resolution))\n        camera.setdefault(\"sensor_width_mm\", 36.0)\n        if scene is not None and scene.camera is not None:\n            cam = scene.camera\n            camera.update(matrix_world=[list(row) for row in cam.matrix_world],\n                          sensor_width_mm=float(cam.data.sensor_width),\n                          sensor_fit=cam.data.sensor_fit)\n            if cam.data.type == \"ORTHO\":\n                camera.update(projection=\"orthographic\", ortho_scale=float(cam.data.ortho_scale))\n            else:\n                camera.update(projection=\"perspective\", lens_mm=float(cam.data.lens))\n        frames = gt.get(\"frames\", [])\n        # toy_car_bottle retains its raw simulation and render_frames as well.\n        rendered = gt.get(\"render_frames\", [])\n        for index, frame in enumerate(frames):\n            frame.setdefault(\"frame_index\", frame.get(\"frame\", index + 1))\n            frame.setdefault(\"time_sec\", frame.get(\"time\", index / gt.get(\"fps\", 24)))\n            if camera.get(\"matrix_world\") is not None:\n                frame.setdefault(\"camera_matrix_world\", camera[\"matrix_world\"])\n            if index < len(rendered):\n                for name, state in rendered[index].get(\"objects\", {}).items():\n                    raw = frame.get(\"objects\", {}).get(name, {})\n                    frame[name] = dict(raw, present=True, location=state[\"position\"],\n                                       quaternion_xyzw=state[\"quaternion_xyzw\"],\n                                       matrix_world=_matrix(state[\"position\"], state[\"quaternion_xyzw\"]))\n        gt.setdefault(\"frame_start\", 1)\n        gt.setdefault(\"frame_end\", len(frames))\n        if scene_name == \"toy_car_bottle\":\n            layout = gt[\"config\"][\"layout\"]\n            gt[\"objects\"] = {\n                \"car\": {\"object_name\": \"toy_car\", \"dimensions\": [layout[\"car_length\"], layout[\"car_width\"], layout[\"car_height\"]]},\n                \"bottle\": {\"object_name\": \"plastic_bottle\", \"radius\": layout[\"bottle_radius\"], \"height\": layout[\"bottle_height\"]},\n            }\n        # A short diagnostic clip may not contain an impact. Its unavailable\n        # post-contact quality measurements are null; poses must stay finite.\n        for container in (gt, gt.get(\"physics\", {})):\n            if \"quality\" in container:\n                container[\"quality\"] = _optional_metrics(container[\"quality\"])\n        for frame in frames:\n            matrices = [item[\"matrix_world\"] for item in frame.values()\n                        if isinstance(item, dict) and \"matrix_world\" in item\n                        and not (item.get(\"present\") is False and item[\"matrix_world\"] is None)]\n            matrices += [item for key, item in frame.items() if key.endswith(\"_matrix_world\")]\n            for matrix in matrices:\n                if matrix is None:\n                    raise ValueError(\"A present object must have a ground-truth transform\")\n                if not all(math.isfinite(value) for row in matrix for value in row):\n                    raise ValueError(\"Non-finite ground-truth transform\")\n        gt_path.write_text(json.dumps(gt, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n    mode = getattr(args, \"mode\", \"preview\")\n    if mode == \"animation\":\n        stem = \"basketball_door\" if scene_name == \"home_basketball_door\" else scene_name\n        source = out / (stem + \".mp4\")\n        target = out / \"video.mp4\"\n        if source.is_file() and not (scene_name == \"uneven_ground_ball\" and getattr(args, \"label\", False)):\n            shutil.copy2(source, target)\n        if not target.is_file():\n            raise FileNotFoundError(f\"Animation did not produce {target}\")\n    refresh_alias = scene_name in (\"home_basketball_door\", \"pot_lid_drop\") or (\n        scene_name == \"toy_car_bottle\" and getattr(args, \"preview_frame\", None) is None)\n    if mode == \"preview\" and (refresh_alias or not (out / \"preview.png\").is_file()):\n        number = getattr(args, \"preview_frame\", None) or 1\n        candidates = [out / f\"preview_frame_{number:04d}.png\", out / \"first_frame.png\"]\n        candidates += sorted(out.glob(\"preview_frame_*.png\"))\n        source = next((p for p in candidates if p.is_file()), None)\n        if source is None:\n            raise FileNotFoundError(f\"Preview did not produce an image in {out}\")\n        shutil.copy2(source, out / \"preview.png\")\n\n\ndef run_renderer(main, scene_name):\n    global _render_args\n    _render_args = None\n    main()\n    if _render_args is not None:\n        import bpy\n        finalize_render_outputs(_render_args.out_dir, scene_name, _render_args, bpy.context.scene)\n", "pcve_blender_compat": "\"\"\"Small Blender 3.6/4.x API differences used by the scene renderers.\"\"\"\n\nSOCKET_NAMES = {\n    \"Coat Weight\": \"Clearcoat\", \"Coat Roughness\": \"Clearcoat Roughness\",\n    \"Specular IOR Level\": \"Specular\", \"Transmission Weight\": \"Transmission\",\n    \"Emission Color\": \"Emission\", \"Sheen Weight\": \"Sheen\",\n    \"Sheen Roughness\": \"Roughness\", \"Subsurface Weight\": \"Subsurface\",\n}\n\n\ndef shader_socket(node, name):\n    socket = node.inputs.get(name)\n    if socket is None:\n        socket = node.inputs.get(SOCKET_NAMES.get(name, name))\n    if socket is None:\n        raise KeyError(f\"{node.name}: missing shader input {name}\")\n    return socket\n\n\ndef set_shader_input(node, name, value):\n    socket = shader_socket(node, name)\n    if socket.type == \"VALUE\" and isinstance(value, (tuple, list)):\n        value = sum(value[:3]) / 3\n    socket.default_value = value\n\n\ndef eevee_engine():\n    import bpy\n    return \"BLENDER_EEVEE_NEXT\" if bpy.app.version >= (4, 2, 0) else \"BLENDER_EEVEE\"\n\n\ndef set_eevee_property(settings, name, value):\n    parts = name.split(\".\")\n    for part in parts[:-1]:\n        if not hasattr(settings, part):\n            return\n        settings = getattr(settings, part)\n    if hasattr(settings, parts[-1]):\n        setattr(settings, parts[-1], value)\n\n\ndef set_color_property(settings, name, value):\n    try:\n        setattr(settings, name, value)\n    except (TypeError, ValueError):\n        candidates = (\"Filmic\", \"Standard\") if name == \"view_transform\" else (\"Medium High Contrast\", \"None\")\n        for candidate in candidates:\n            try:\n                setattr(settings, name, candidate)\n                return\n            except (TypeError, ValueError):\n                continue\n        raise\n\n\ndef configure_cycles_device(bpy, scene, requested):\n    scene.cycles.device = \"CPU\"\n    scene.render.threads_mode = \"FIXED\"\n    scene.render.threads = 4\n    if requested == \"cpu\":\n        return \"CPU\"\n    prefs = bpy.context.preferences.addons[\"cycles\"].preferences\n    for backend in (\"OPTIX\", \"CUDA\", \"HIP\", \"METAL\"):\n        try:\n            prefs.compute_device_type = backend\n            prefs.get_devices()\n            found = [device for device in prefs.devices if device.type == backend]\n            if found:\n                for device in prefs.devices:\n                    device.use = device.type == backend\n                scene.cycles.device = \"GPU\"\n                return \"GPU\"\n        except (TypeError, RuntimeError, ValueError):\n            continue\n    return \"CPU\"\n", "pcve_legacy_scene": "\"\"\"Original batch/suite workflow for scenes backed by a scenario.json file.\"\"\"\n\nimport argparse\nimport hashlib\nimport importlib\nimport json\nimport random\nimport shutil\nimport subprocess\nimport time\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n\nfrom pcve_scene_runtime import ROOT, add_build_arguments, append_render_options, render_prefix, implementation_hashes, case_outputs\n\nimport pcve_edit_dsl as dsl\n\n\nSCRIPTS = {\n    \"home_basketball_door\": (\"render_home_basketball_door.py\", \"simulate_home_basketball_door.py\"),\n    \"pot_lid_drop\": (\"render_pot_lid_drop.py\", \"simulate_pot_lid_drop.py\"),\n    \"toy_car_bottle\": (\"render_toy_car_bottle.py\", \"simulate_toy_car_bottle.py\"),\n}\n\n\ndef write_json(path, data):\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(data, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n\n\ndef parser(scene, batch=False):\n    p = argparse.ArgumentParser(description=f\"Build {'randomized samples' if batch else 'a source/edit suite'} for {scene}.\")\n    p.add_argument(\"--out-root\", type=Path, default=ROOT / \"renders\" / (f\"batch_{scene}\" if batch else f\"pcve_{scene}_suite\"))\n    p.add_argument(\"--resolution\", nargs=2, type=int, default=[1280, 720])\n    p.add_argument(\"--fps\", type=int, default=24)\n    p.add_argument(\"--duration-sec\", type=float, default=4.0)\n    p.add_argument(\"--samples\", type=int, default=32)\n    p.add_argument(\"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    p.add_argument(\"--mode\", choices=(\"preview\", \"animation\"), default=\"preview\" if batch else \"animation\")\n    p.add_argument(\"--skip-existing\", action=\"store_true\")\n    p.add_argument(\"--dry-run\", action=\"store_true\")\n    p.add_argument(\"--verbose-render\", action=\"store_true\")\n    p.add_argument(\"--simulate-only\", action=\"store_true\")\n    if batch:\n        p.add_argument(\"--count\", type=int, default=4)\n        p.add_argument(\"--start-index\", type=int, default=0)\n        p.add_argument(\"--seed-base\", type=int, default=7200)\n    else:\n        p.add_argument(\"--cases\", nargs=\"+\")\n        p.add_argument(\"--clean-stale-cases\", action=\"store_true\")\n    return add_build_arguments(p)\n\n\ndef scene_directory(scene):\n    candidates = (ROOT / \"clean_scripts\" / scene, ROOT / \"clean_scripts\" / scene)\n    for directory in candidates:\n        if directory.is_dir():\n            return directory\n    raise FileNotFoundError(f\"No scene directory found for {scene}: {candidates}\")\n\n\ndef command_for(scene, folder, args, seed, overrides):\n    render, simulate = SCRIPTS[scene]\n    directory = scene_directory(scene)\n    if args.simulate_only:\n        command = [str(args.physics_python), str(directory / simulate), \"--out\", str(folder / \"physics_transforms.json\")]\n    else:\n        command = render_prefix(args, directory / render)\n        command += [\"--out-dir\", str(folder), \"--mode\", args.mode,\n                    \"--resolution\", *map(str, args.resolution), \"--samples\", str(args.samples),\n                    \"--physics-python\", str(args.physics_python), \"--seed\", str(seed)]\n        append_render_options(command, args)\n    command += [\"--fps\", str(args.fps), \"--duration-sec\", str(args.duration_sec)]\n    if overrides is not None:\n        command += [\"--scenario-overrides-json\", str(overrides)]\n    return command\n\n\ndef run_case(scene, folder, args, seed, override):\n    folder = folder.resolve()\n    overrides = folder / \"scenario_overrides.json\" if override else None\n    command = command_for(scene, folder, args, seed, overrides)\n    if args.dry_run:\n        print(subprocess.list2cmdline(command))\n        return {\"status\": \"dry_run\"}\n    implementation = implementation_hashes(scene_directory(scene))\n    payload = dict(override=override, implementation=implementation, seed=seed, fps=args.fps,\n                   duration=args.duration_sec, mode=args.mode, samples=args.samples,\n                   resolution=args.resolution, engine=args.engine, device=args.device,\n                   preview_frame=args.preview_frame, simulation_only=args.simulate_only)\n    fp = hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()\n    status_path = folder / \"run_status.json\"\n    required = [\"physics_transforms.json\"] if args.simulate_only else [\n        \"ground_truth_transforms.json\", \"scenario_metadata.json\",\n        \"video.mp4\" if args.mode == \"animation\" else \"preview.png\"]\n    if args.skip_existing and status_path.is_file():\n        previous = json.loads(status_path.read_text(encoding=\"utf-8\"))\n        if previous.get(\"fingerprint\") == fp and all((folder / p).is_file() for p in required):\n            return dict(previous, status=\"skipped_existing\")\n    if overrides is not None:\n        write_json(overrides, override)\n    folder.mkdir(parents=True, exist_ok=True)\n    start = time.perf_counter()\n    if args.verbose_render:\n        subprocess.run(command, check=True)\n    else:\n        with (folder / \"render.log\").open(\"w\", encoding=\"utf-8\") as log:\n            subprocess.run(command, stdout=log, stderr=subprocess.STDOUT, check=True)\n    for name in required:\n        if not (folder / name).is_file():\n            raise FileNotFoundError(folder / name)\n    status = dict(status=\"completed\", valid=True, fingerprint=fp, simulation_only=args.simulate_only,\n                  render_mode=args.mode, elapsed_sec=round(time.perf_counter() - start, 3),\n                  outputs=case_outputs(folder))\n    write_json(status_path, status)\n    return status\n\n\ndef batch_main(scene, argv=None):\n    args = parser(scene, batch=True).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    if args.count < 1 or args.start_index < 0:\n        raise ValueError(\"Count must be positive and start index nonnegative\")\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    vocab = importlib.import_module(f\"{scene}.edit_vocab\").VOCAB\n    manifest = dict(schema_version=1, scene=scene, mode=args.mode, count=args.count,\n                    start_index=args.start_index, seed_base=args.seed_base, samples=[])\n    for offset in range(args.count):\n        index = args.start_index + offset\n        seed = args.seed_base + index\n        rng = random.Random(seed)\n        params = dict(vocab.baseline_physics)\n        for binding in vocab.sim_bindings.values():\n            if isinstance(binding, dsl.SimBinding) and isinstance(params[binding.key], (int, float)):\n                params[binding.key] *= rng.uniform(.8, 1.2)\n        folder = args.out_root / f\"sample_{index:04d}\"\n        result = run_case(scene, folder, args, seed, {\"physics\": params})\n        manifest[\"samples\"].append(dict(sample_index=index, seed=seed, params=params,\n                                         out_dir=str(folder), **result))\n        if not args.dry_run:\n            write_json(args.out_root / \"batch_manifest.json\", manifest)\n\n\ndef suite_main(scene, argv=None):\n    args = parser(scene).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    module = importlib.import_module(f\"{scene}.edit_vocab\")\n    vocab = module.VOCAB\n    source_id = f\"{scene}_baseline\"\n    cases = list(module.EDIT_CASES)\n    if args.cases:\n        unknown = set(args.cases) - {source_id, *[name for name, _ in cases]}\n        if unknown:\n            raise ValueError(f\"Unknown cases: {sorted(unknown)}\")\n        cases = [(name, instruction) for name, instruction in cases if name in args.cases]\n    if args.clean_stale_cases and not args.dry_run:\n        keep = {source_id, *[name for name, _ in module.EDIT_CASES]}\n        for folder in (args.out_root / \"cases\").glob(\"*\"):\n            if folder.is_dir() and folder.name not in keep:\n                if not folder.resolve().is_relative_to(args.out_root):\n                    raise ValueError(f\"Unsafe case directory: {folder}\")\n                shutil.rmtree(folder)\n    manifest = dict(schema_version=3, suite_name=f\"pcve_{scene}_suite\", scene=scene,\n                    baseline_physics=vocab.baseline_physics, total_frames=round(args.fps * args.duration_sec),\n                    fps=args.fps, duration_sec=args.duration_sec, physical_duration_sec=args.duration_sec,\n                    playback_duration_sec=args.duration_sec, slow_motion=1, sample_fps=args.fps,\n                    samples=args.samples, resolution=args.resolution, source=None, edits=[])\n    path = args.out_root / \"suite_manifest.json\"\n    for index, (case_id, instruction) in enumerate([(source_id, None), *cases]):\n        folder = args.out_root / \"cases\" / case_id\n        record = dict(case_id=case_id, kind=\"edit\" if instruction else \"source\",\n                      case_dir=str(folder), seed=7300 + index, status=\"pending\")\n        override = None\n        if instruction:\n            edit = dsl.parse(instruction, vocab)\n            override = {\"physics\": dsl.to_scenario_override(edit, vocab)}\n            record.update(source_case_id=source_id, edit_dsl=instruction,\n                          edit_summary=\"Change the declared physical parameter and simulate the resulting rigid-body interaction.\",\n                          applies_from_frame=dsl.starts_at_frame(edit), prompts=dsl.make_prompts(edit, vocab),\n                          physics_diff={f\"{edit.property_name} ({edit.object_id})\": {\n                              \"from\": dsl.baseline_value_for(edit, vocab), \"to\": dsl.resolved_to_value(edit, vocab)},\n                              \"timing\": dsl.timing_diff(edit, vocab)})\n            manifest[\"edits\"].append(record)\n        else:\n            record[\"description\"] = module.DESCRIPTION\n            manifest[\"source\"] = record\n        if not args.dry_run:\n            prompts = dict(schema_version=2 if instruction else 1, **record)\n            if not instruction:\n                prompts[\"prompts\"] = module.DESCRIPTION\n            write_json(folder / \"prompts.json\", prompts)\n            write_json(path, manifest)\n        try:\n            record.update(run_case(scene, folder, args, record[\"seed\"], override))\n        except Exception:\n            record[\"status\"] = \"failed\"\n            write_json(path, manifest)\n            raise\n        if not args.dry_run:\n            write_json(path, manifest)\n", "pcve_render_quality": "\"\"\"Appearance render setup only; no simulation settings or shared project edits.\"\"\"\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(Path(__file__).resolve().parents[2]))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\ndef configure_renderer(bpy,scene,args):\n    scene.render.engine=eevee_engine() if args.engine=='eevee' else 'CYCLES'\n    if args.engine=='eevee':\n        set_eevee_property(scene.eevee, 'taa_render_samples', args.samples);set_eevee_property(scene.eevee, 'use_raytracing', False)\n        set_eevee_property(scene.eevee, 'ray_tracing_options.resolution_scale', '2');set_eevee_property(scene.eevee, 'ray_tracing_options.screen_trace_quality', 0.6)\n        set_eevee_property(scene.eevee, 'use_gtao', True);set_eevee_property(scene.eevee, 'gtao_distance', 0.2);set_eevee_property(scene.eevee, 'gtao_quality', 1.0)\n        set_eevee_property(scene.eevee, 'shadow_ray_count', 1);set_eevee_property(scene.eevee, 'shadow_step_count', 8)\n    else:\n        scene.cycles.samples=args.samples;scene.cycles.use_denoising=True;scene.cycles.max_bounces=8;scene.cycles.diffuse_bounces=4;scene.cycles.glossy_bounces=4\n        scene.cycles.adaptive_threshold=.008;scene.cycles.seed=19;scene.render.use_persistent_data=True\n        # Default 1.5 px pixel filter softens fine background detail; 1.0 keeps the\n        # scanned bookshelf textures crisp without aliasing the suspension threads.\n        scene.cycles.filter_width=1.0\n        scene.cycles.device='CPU'\n        if args.device=='auto':\n            prefs=bpy.context.preferences.addons['cycles'].preferences\n            try:\n                prefs.compute_device_type='CUDA';prefs.get_devices();available=[dev for dev in prefs.devices if dev.type=='CUDA']\n                for dev in prefs.devices:dev.use=(dev.type=='CUDA')\n                if available:\n                    scene.cycles.device='GPU';scene.cycles.denoiser='OPTIX' if any(dev.type=='OPTIX' for dev in prefs.devices) else 'OPENIMAGEDENOISE'\n                    print('[render] CUDA: '+', '.join(dev.name for dev in available),flush=True)\n            except Exception as exc:\n                scene.cycles.device='CPU';scene.cycles.denoiser='OPENIMAGEDENOISE'\n                print('[render] CPU fallback: '+str(exc),flush=True)\n        return scene.cycles.device\n    return 'GPU'\n\n\ndef configure_color(scene):\n    set_color_property(scene.view_settings, 'view_transform', 'AgX');set_color_property(scene.view_settings, 'look', 'AgX - Medium High Contrast');scene.view_settings.exposure=-.22\n\n\ndef prepare_eevee(bpy,scene,moving):\n    if scene.render.engine!=eevee_engine() or bpy.app.version<(4,2,0):return\n    for light in bpy.data.lights:light.use_shadow_jitter=False\n    scene.use_nodes=True;nodes=scene.node_tree.nodes;links=scene.node_tree.links;nodes.clear()\n    layers=nodes.new('CompositorNodeRLayers');denoise=nodes.new('CompositorNodeDenoise');denoise.use_hdr=True\n    composite=nodes.new('CompositorNodeComposite');links.new(layers.outputs['Image'],denoise.inputs['Image']);links.new(denoise.outputs['Image'],composite.inputs['Image'])\n    probe_data=bpy.data.lightprobes.new('Static room irradiance','VOLUME');probe_data.resolution_x=6;probe_data.resolution_y=4;probe_data.resolution_z=4;probe_data.bake_samples=32;probe_data.surfel_density=10\n    probe=bpy.data.objects.new('Static room irradiance',probe_data);scene.collection.objects.link(probe);probe.location=[.2,.5,1.3];probe.scale=[2.5,2.2,1.6]\n    dynamic=list(moving)\n    for obj in list(dynamic):dynamic.extend(obj.children_recursive)\n    dynamic=list(dict.fromkeys(dynamic));previous=[obj.hide_render for obj in dynamic]\n    try:\n        for obj in dynamic:obj.hide_render=True\n        bpy.context.view_layer.objects.active=probe;probe.select_set(True)\n        print('[render] Baking static room indirect light',flush=True);bpy.ops.object.lightprobe_cache_bake(subset='ALL')\n    finally:\n        for obj,hidden in zip(dynamic,previous):obj.hide_render=hidden\n", "scene_support": "", "scene_support.pool_break.cache_contract": "\"\"\"Compatibility contract for pool-break trajectories and renderer replays.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib\nimport json\nfrom pathlib import Path\n\ndef _scene_directory():\n    scripts_root = _PCVE_ROOT / 'clean_scripts'\n    for candidate in (scripts_root / \"rigid_rigid\" / \"pool_break\", scripts_root / \"pool_break\"):\n        if candidate.is_dir():\n            return candidate\n    raise FileNotFoundError(\"Scene directory not found for pool_break\")\n\n\nCACHE_SCHEMA_VERSION = 4\n\n\ndef signature(parameters):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=parameters)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(data, requested=None):\n    message = (\n        \"Incompatible pool-break physics cache: parameters, geometry or \"\n        \"implementation changed; resimulate first.\"\n    )\n    if data.get(\"schema_version\") != CACHE_SCHEMA_VERSION or data.get(\"scene\") != \"pool_break\":\n        raise ValueError(message)\n    params = data.get(\"simulation_parameters\", {})\n    if data.get(\"simulation_signature\") != signature(params):\n        raise ValueError(message)\n    for name, value in (requested or {}).items():\n        if value is not None and params.get(name) != value:\n            raise ValueError(message + \" Mismatch: \" + name)\n    count = max(2, round(params[\"fps\"] * params[\"duration_sec\"]))\n    if (\n        data.get(\"fps\") != params[\"fps\"]\n        or data.get(\"duration_sec\") != params[\"duration_sec\"]\n        or data.get(\"frame_end\") != count\n        or len(data.get(\"frames\", [])) != count\n    ):\n        raise ValueError(message)\n    for name, value in data.get(\"physics_parameters\", {}).items():\n        if name in params and value != params[name]:\n            raise ValueError(message)\n", "scene_support.pool_break.props": "\"\"\"The seating and the bin for the pool hall.\n\nFurniture in this room has been rebuilt twice. First it was primitives -- a\nbench, a side table, a chair and a cabinet, each one a box or two standing on\nlegs. They were enough to say \"room\", but they said it the only way a box can:\nno upholstery, no seat, square edges, a silhouette that reads \"proxy\" the moment\nyou look at it for more than a second.\n\nThen the seating came from ``jayden_miles_individual_modular_props``: two chairs\nwith blue cushions and white frames, and a black bin. Better than boxes, but the\npack is a mobile-game asset -- the chairs are flat-shaded with a single 512 px\nmap, and at four metres their frames are the brightest thing in the frame after\nthe cloth, which pulls the eye off the break.\n\nThe chairs are now ``rustic_chair.glb``: a scanned wooden chair with a 2k map,\nreal joinery at the stretchers and a worn seat. Two copies, because a hall seats\nmore than one person. The bin still comes from the props pack -- a barrel is a\nbarrel, and it is meant to be the black shape in the frame.\n\nScale\n-----\nThe props pack is a Sketchfab export of an FBX whose units are centimetres, and\nSketchfab's root matrix divides by 100 on the way in, so its meshes arrive at a\ntenth of their authored size -- a chair 0.08 m tall. ``PROPS_IMPORT_SCALE`` puts\nthem back. The rustic chair does not need that correction: it arrives at 0.55 x\n0.53 x 0.96 m, which is a chair, so it keeps its own scale.\n\nSource (chairs): https://sketchfab.com/3d-models/rustic-chair (CC-BY-4.0)\nSource (bin): https://sketchfab.com/3d-models/jayden-miles-individual-modular-props-67e7db80574443338eb112125117d5e1\n(jamiles, CC-BY-4.0)\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport math\nfrom pathlib import Path\n\nimport bpy\nfrom mathutils import Vector\n\nPROPS_MODEL_PATH = (\n    _PCVE_ROOT / \"assets\" / \"models\" / \"jayden_miles_individual_modular_props.glb\"\n)\nCHAIR_MODEL_PATH = _PCVE_ROOT / \"assets\" / \"models\" / \"rustic_chair.glb\"\n\n# See the module docstring: the import already divided the authored centimetres\n# by 100, so this factor is what restores them.\nPROPS_IMPORT_SCALE = 10.0\n\nTRASHBIN_MESH = \"Trashbin_Mat_Trashbin_0\"\nKEPT_MESHES = (TRASHBIN_MESH,)\n\n\ndef _flatten(obj: bpy.types.Object, scale: float = 1.0) -> None:\n    \"\"\"Detach ``obj`` from its hierarchy with its world transform baked in.\n\n    After this the object's origin sits at the centre of its own bounds and its\n    mesh is in metres, so placing it means setting ``location`` and turning it --\n    not undoing an inherited hierarchy whose scale is 100 on one level and 0.001\n    on the next.\n    \"\"\"\n    world = obj.matrix_world.copy()\n    obj.parent = None\n    obj.matrix_world = world\n    if scale != 1.0:\n        obj.scale = (\n            obj.scale.x * scale,\n            obj.scale.y * scale,\n            obj.scale.z * scale,\n        )\n    bpy.ops.object.select_all(action=\"DESELECT\")\n    obj.select_set(True)\n    bpy.context.view_layer.objects.active = obj\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n    bpy.ops.object.origin_set(type=\"ORIGIN_GEOMETRY\", center=\"BOUNDS\")\n    obj.select_set(False)\n    # The glTF importer leaves these in quaternion mode, where ``rotation_euler``\n    # is a stale copy of the last quaternion and writing to it does nothing at\n    # all. Everything downstream turns the props by yaw, so switch them to Euler\n    # up front.\n    obj.rotation_mode = \"XYZ\"\n\n\ndef import_props() -> dict[str, bpy.types.Object]:\n    \"\"\"Import the props pack, keep the bin, hide the rest.\n\n    Returns the kept object keyed by mesh name, already scaled to metres.\n    \"\"\"\n    # Remember what was already in the file. The scene is built in pieces --\n    # the table, the room, then these props -- and \"hide everything I did not\n    # keep\" has to mean \"everything this import brought in\", or it hides the\n    # walls and the table as well.\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(PROPS_MODEL_PATH))\n    imported = [obj for obj in bpy.data.objects if obj not in before]\n\n    kept: dict[str, bpy.types.Object] = {}\n    for obj in imported:\n        if obj.type != \"MESH\":\n            continue\n        if obj.name in KEPT_MESHES:\n            _flatten(obj, PROPS_IMPORT_SCALE)\n            kept[obj.name] = obj\n        else:\n            # The pack's own chairs, table and rails: the scene supplies its own.\n            obj.hide_viewport = True\n            obj.hide_render = True\n    bpy.context.view_layer.update()\n    return kept\n\n\ndef import_chairs(count: int = 2) -> list[bpy.types.Object]:\n    \"\"\"Import ``rustic_chair.glb`` and return ``count`` independently placeable chairs.\n\n    One import, then copies: the copies share the mesh data (nothing downstream\n    edits vertices, only object transforms) but each gets its own object, so\n    ``place`` can stand them in different spots and at different angles.\n    \"\"\"\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(CHAIR_MODEL_PATH))\n    imported = [obj for obj in bpy.data.objects if obj not in before]\n    meshes = [obj for obj in imported if obj.type == \"MESH\"]\n    if not meshes:\n        raise RuntimeError(f\"No mesh found in {CHAIR_MODEL_PATH.name}\")\n    for obj in imported:\n        if obj.type != \"MESH\":\n            obj.hide_viewport = True\n            obj.hide_render = True\n\n    chair = meshes[0]\n    _flatten(chair)\n    chair.name = \"rustic_chair\"\n\n    chairs = [chair]\n    for index in range(1, count):\n        copy = chair.copy()\n        copy.name = f\"rustic_chair_{index + 1}\"\n        bpy.context.scene.collection.objects.link(copy)\n        chairs.append(copy)\n    bpy.context.view_layer.update()\n    return chairs\n\n\ndef yaw_facing(dx: float, dy: float) -> float:\n    \"\"\"The yaw that turns a prop's front toward the direction ``(dx, dy)``.\n\n    Both the rustic chair and the pack's bin face model -Y (measured off the\n    meshes: a chair's backrest is the only geometry above seat height, and on\n    the rustic chair it sits on the +Y side; the bin is a barrel and does not\n    care). A Blender Z rotation of ``theta`` sends that front to\n    ``(sin t, -cos t)``, so ``theta = atan2(dx, -dy)`` is the one that points it\n    at ``(dx, dy)``.\n    \"\"\"\n    return math.atan2(dx, -dy)\n\n\ndef drop_to_floor(obj: bpy.types.Object, floor_z: float) -> None:\n    \"\"\"Put the object on the floor without touching its mesh.\n\n    The meshes carry their authored offset in the vertices, so \"on the floor\"\n    is a question about the lowest point of the world-space bounding box, not\n    about the object's origin.\n    \"\"\"\n    bpy.context.view_layer.update()\n    lowest = min((obj.matrix_world @ Vector(corner)).z for corner in obj.bound_box)\n    obj.location.z += floor_z - lowest\n    bpy.context.view_layer.update()\n\n\ndef place(obj: bpy.types.Object, x: float, y: float, yaw: float, floor_z: float) -> None:\n    \"\"\"Move the object to ``(x, y)``, turn it to ``yaw`` and stand it on the floor.\n\n    ``yaw`` is measured the Blender way: 0 rad points the model's front along\n    -Y, and positive yaw turns it counter-clockwise seen from above.\n    \"\"\"\n    obj.rotation_mode = \"XYZ\"\n    obj.rotation_euler = (0.0, 0.0, yaw)\n    obj.location.x = x\n    obj.location.y = y\n    drop_to_floor(obj, floor_z)\n\n\ndef face_towards(obj: bpy.types.Object, x: float, y: float,\n                 target_x: float, target_y: float, floor_z: float) -> None:\n    \"\"\"Stand the object at ``(x, y)`` turned to look at ``(target_x, target_y)``.\"\"\"\n    place(obj, x, y, yaw_facing(target_x - x, target_y - y), floor_z)\n", "scene_support.pool_break.runtime_support": "\"\"\"Local runtime discovery; scripts also work in ordinary Python/Blender installs.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport os\nimport sys\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\n_dll_handles = []\nif os.name == \"nt\":\n    directory = Path(sys.prefix) / \"Library/bin\"\n    if directory.exists():\n        _dll_handles.append(os.add_dll_directory(str(directory)))\n\n\ndef python_for(role):\n    sys.path.insert(0, str(ROOT/'clean_scripts'))\n    from pcve_scene_runtime import python_for as resolve_python\n    return resolve_python(role)\n", "scene_support.pool_break.scene_config": "\"\"\"Shared geometry and baseline parameters for the pool-break scene.\n\nBoth the PyBullet simulation and the Blender renderer import these constants, so\nthe collision bodies and the visible meshes cannot drift apart and the scene's\nthree exposed controls have exactly one definition.\n\nWorld conventions\n-----------------\n* The table's long axis is **X**. The cue ball breaks from ``+X`` towards\n  ``-X``, so the camera sits behind the cue at ``+X`` and looks down the table.\n* **+Y** is the far side of the table as seen from that camera's default rig\n  (forward ``-X``, up ``+Z`` => screen-right is ``+Y``), which is why a\n  positive ``cue_contact_offset`` reads as \"hit the right side of the apex\n  ball\" rather than as an abstract axis sign.\n* The felt surface is world ``z = 0``; every ball centre sits at ``z = radius``.\n  The imported table model is shifted down by its own felt height so the two\n  frames coincide -- see :func:`model_z_shift`.\n\nWhy the scene is scaled by the ball, not by the table\n-----------------------------------------------------\n``pool_table_animation.glb`` is authored in FBX centimetres: the felt mesh\nmeasures 1200.7 x 621.8 units and every ball mesh has a 18.93-unit radius. A\nreal 57.15 mm ball against that felt would make a 3.6 m table, so the model's\nballs are oversized relative to its cloth. Scaling so the *balls* are\nregulation (``SCENE_SCALE``) instead gives a 1.81 x 0.94 m playing surface --\na compact bar table, which is a real thing -- and keeps every number that the\nphysics cares about (ball/ball contact, cue speed, gravity) in familiar units.\nScaling by the table instead would leave 76 mm balls that visibly do not behave\nlike billiard balls at this camera distance.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nfrom pathlib import Path\n\n# ---------------------------------------------------------------- the model\n\nMODEL_PATH = _PCVE_ROOT / \"assets\" / \"models\" / \"pool_table_animation.glb\"\n\n# Measured off the model: every ball mesh is a sphere of this radius, the felt\n# mesh is a flat sheet at this height, and the cushion nose sits at the felt\n# edge (the vertex scan put it within 1.5 units of the felt bound).\nMODEL_BALL_RADIUS_UNITS = 18.9315\nMODEL_FELT_TOP_Z_UNITS = 100.012\nMODEL_PLAY_HALF_X_UNITS = 598.9\nMODEL_PLAY_HALF_Y_UNITS = 309.4\nMODEL_FLOOR_Z_UNITS = -363.94        # bottom of the legs, for the visual floor\n\n# Regulation pool ball: 57.15 mm diameter.\nBALL_RADIUS = 0.028575\nSCENE_SCALE = BALL_RADIUS / MODEL_BALL_RADIUS_UNITS\n\nPLAY_HALF_X = MODEL_PLAY_HALF_X_UNITS * SCENE_SCALE      # 0.904 m\nPLAY_HALF_Y = MODEL_PLAY_HALF_Y_UNITS * SCENE_SCALE      # 0.467 m\nMODEL_FLOOR_Z = MODEL_FLOOR_Z_UNITS * SCENE_SCALE\n\n\ndef model_z_shift() -> float:\n    \"\"\"How far to drop the imported table so its felt lands on world ``z = 0``.\"\"\"\n    return MODEL_FELT_TOP_Z_UNITS * SCENE_SCALE\n\n\n# Which mesh in the GLB plays which part. The file ships a full rack of\n# fifteen numbered balls plus a white cue ball and two cue sticks; the scene\n# only uses four of them and hides the rest, exactly the way\n# ``pool_collision`` hides the balls its shot does not use.\nCUE_BALL_MESH = \"Ball Clube_10 - Default_0\"\nAPEX_BALL_MESH = \"Ball1_01 - Default_0\"\nLEFT_BALL_MESH = \"Ball2_Material #158_0\"\nRIGHT_BALL_MESH = \"Ball3_Material #157_0\"\n# Hidden on import: the rest of the rack, and both sticks (this scene drives\n# the cue ball kinematically at frame 1 rather than animating a stick).\nUNUSED_BALL_PREFIX = \"Ball\"\nCUE_STICK_PREFIXES = (\"Cue stick\", \"Cue stick2\")\n\n# ----------------------------------------------------------------- the rack\n# The foot spot is the middle of the far half of the table, which is where a\n# rack is set in every published rule set.\nFOOT_SPOT_X = -PLAY_HALF_X / 2.0\n# Cue ball starts behind the head string and drives 1.05 m up the table.\nCUE_START_X = 0.60\n# A 0.5 mm air gap between the racked balls. Placing them exactly touching\n# makes Bullet resolve an initial overlap with a separation impulse on frame 1,\n# which pushes the rack apart before the cue ball has moved.\nRACK_GAP = 0.0005\n\n\ndef rack_centres() -> dict[str, tuple[float, float]]:\n    \"\"\"Where the three racked balls sit, in the table plane.\n\n    An equilateral triangle pointing at the cue ball: the apex on the foot\n    spot, the other two one centre-to-centre distance behind it. The apex is\n    therefore wedged between the two rear balls, which is what turns a cue-ball\n    impact into a break instead of into a single ball rolling away from an\n    untouched pair.\n\n    The rear pair sits at ``(-d * sqrt(3)/2, +/- d/2)`` relative to the apex --\n    half a spacing to either side, three quarters of a spacing back. That is the\n    first three balls of a real rack: the apex angle seen from the cue ball is\n    60 degrees, so each rear ball sits 30 degrees off the cue's line, and all\n    three pairs are one full spacing apart. Getting this the wrong way round\n    (rear pair at ``(-d/2, +/- d * sqrt(3)/2)``) still touches the apex but\n    leaves the two rear balls 1.73 spacings apart with a hole between them: a\n    flat 120-degree wedge that no rack has ever looked like, and the \"triangle\"\n    reads as two balls flanking a third from a distance.\n    \"\"\"\n    d = 2.0 * BALL_RADIUS + RACK_GAP\n    back = d * 0.8660254037844386\n    across = d * 0.5\n    return {\n        \"apex_ball\": (FOOT_SPOT_X, 0.0),\n        \"right_ball\": (FOOT_SPOT_X - back, +across),\n        \"left_ball\": (FOOT_SPOT_X - back, -across),\n    }\n\n\n# ---------------------------------------------------------------- physics\n\n# The three controls the benchmark exposes.\nBASELINE_PHYSICS = {\n    # A medium break: about 3.6 m/s of cue-ball speed. On a 1.8 m table this\n    # carries the cue ball 1.05 m to the rack in a quarter of a second and\n    # spreads the triangle to the cushions inside the clip.\n    \"cue_speed\": 3.6,            # m/s\n    # Signed lateral offset of the cue ball's line of travel from the apex\n    # ball's centre. + is the apex ball's right side (screen-right); +/-\n    # one ball radius is a half-ball hit, 2 radii is a clean miss.\n    #\n    # Deliberately not 0. A dead-centre hit is a stun shot: the cue ball comes\n    # straight back down its own line (+/-180 degrees) and the rack opens with\n    # perfect mirror symmetry, which no real break does and which makes the\n    # shot look like a diagram. 3 mm is 0.05 radii -- invisible at this camera\n    # distance -- but it is already enough to break the symmetry: the cue ball\n    # leaves at 157 degrees instead of coming straight back, and the apex ball\n    # is nudged to one side.\n    \"cue_contact_offset\": 0.003,  # m\n    \"cue_mass\": 0.17,            # kg -- regulation ball\n}\n\n# Everything an edit must NOT move, so a single-variable edit stays single.\nFIXED_PHYSICS = {\n    \"object_mass\": 0.17,\n    # Bullet multiplies the two bodies' coefficients, so the pair that matters\n    # is 0.25 * 0.12 = 0.03. This pair governs the *sliding* phase only -- it is\n    # what stops the cue ball skidding and gets it rolling, and it is kept low\n    # because at 0.6/0.9 the cue ball loses 5.3 m/s^2 and stops a third of the\n    # way to the rack. The loss that lasts, cloth drag, is ``BALL_ROLL_DECEL``.\n    \"ball_friction\": 0.25,\n    \"felt_friction\": 0.12,\n    # Left at zero on purpose. Bullet's rolling-friction constraint on a sphere\n    # does not give a rolling ball a constant drag -- it instead cancels the\n    # spin the contact friction is trying to build, so the ball slides the whole\n    # way at the full lateral coefficient. Cloth drag therefore lives in the\n    # lateral pair above, and the visible roll is reconstructed from each ball's\n    # path by ``simulate_pool_break.rolling_quaternions``.\n    \"ball_rolling_friction\": 0.0,\n    \"ball_spinning_friction\": 0.0,\n    \"ball_restitution\": 0.93,        # ball <-> ball reads 0.93 * 0.93 = 0.86\n    \"felt_restitution\": 0.10,\n    \"cushion_friction\": 0.30,\n    \"cushion_restitution\": 0.72,\n    \"gravity_z\": -9.81,\n}\n\n# Cloth drag, applied explicitly as a constant deceleration (m/s^2).\n#\n# Coulomb friction alone cannot stop a ball: once it rolls without slipping the\n# contact patch is stationary, the friction force drops to zero and a rigid\n# sphere on a rigid plane coasts forever. Real cloth dissipates through fibre\n# deformation and the ball's own hysteresis, which Bullet does not model, and\n# its ``rollingFriction`` term is not usable here (see above -- it fights the\n# spin instead of damping it). So the drag is integrated by hand, and without it\n# the clip ended with four balls still travelling at 0.5-1.2 m/s after five\n# cushion bounces, the triangle width oscillating between 70 mm and 570 mm from\n# frame to frame -- a pinball table, not a break.\n#\n# The value is the physical one. A ball rolling on worsted cloth decelerates at\n# 0.2-0.35 m/s^2 (rolling resistance coefficient 0.02-0.035); 0.30 is the fast\n# end of that band, which is what a brushed worsted cloth under a hard break\n# behaves like. Note that the total loss is not this number alone: while a ball\n# is still sliding it also pays the felt's Coulomb term (``ball_friction`` *\n# ``felt_friction`` * g = 0.29 m/s^2), so the hand-integrated drag is the\n# rolling-phase loss only.\n#\n# This used to be 0.8 to make a 2.5 s clip settle, and 0.8 is what a viewer\n# reads as wrong: it is 3x the real figure, and it stopped every ball by 1.9 s.\n# The constraint that forced it was clip length, and clip length is now 4 s\n# (``BASELINE_RENDER``), so the compromise is gone. At 0.30 the same break runs\n# 2.4 m of path per wing ball instead of 1.2 m -- a wing ball reaches the corner,\n# comes off the end cushion and carries back across the table -- and the last\n# ball dies at 3.96 s, one frame before the end.\n#\n# The two numbers are coupled: shortening the clip below ~3.8 s puts the\n# settling back in the cut-off, and at 2.5 s the two wing balls are still\n# running at 0.39 and 0.48 m/s when the clip ends.\nBALL_ROLL_DECEL = 0.30\n\n# Cushion nose height is 63.5 % of a ball diameter in every table spec.\nCUSHION_HEIGHT = 0.0363\nCUSHION_THICKNESS = 0.05\n# 96 substeps at 24 fps is a 0.43 ms step. The cue ball covers 1.5 mm per\n# substep at the default speed, which is the point: at 48 substeps a fast\n# contact resolves with about 3 mm of penetration on a 28.6 mm radius and the\n# rack visibly pops apart instead of being struck.\nSUBSTEPS_PER_FRAME = 96\n\n# ---------------------------------------------------------------- baseline\n\nBASELINE_RENDER = {\n    \"fps\": 24,\n    # Long enough for the break to finish on its own at the physical cloth\n    # drag: the last ball dies at 3.96 s. A 2.5 s clip (the old default) only\n    # fitted because ``BALL_ROLL_DECEL`` was inflated to stop everything early.\n    \"duration_sec\": 4.0,\n    # Same size every other rigid-body suite in this repo renders at.\n    \"resolution\": (960, 540),\n    \"samples\": 48,\n    \"camera_mode\": \"break\",\n}\n", "scene_support.pool_break.table_model": "\"\"\"The hall's pool table, imported from its own model.\n\nWhy this exists\n---------------\nThe scene used to draw its table out of ``pool_table_animation.glb``, the same\nfile that supplies the four balls. That file is a low-poly game asset: the cloth\nis a single flat sheet, the rails are boxes with the corner pockets cut into\nthem by hand, and the apron is four boards. It was enough to hold the physics,\nbut at 1.5 m from the camera the cloth has no nap, the pockets have no throats\nand the frame has no joinery -- the table reads as a green tray with cushions.\n\nThis module brings in a proper billiard table (felt, cushions, leather pockets,\nturned legs, 4k maps) and fits it to the geometry the simulation already uses,\nso the ball trajectories stay valid. The physics is not touched: the balls are\nstill the meshes from ``pool_table_animation.glb`` and still keyed from the same\nPyBullet run. Only the table under them changes.\n\nFitting it to the simulation\n----------------------------\nEverything the shot cares about is measured off the imported mesh rather than\nguessed (see the ``MODEL_*`` constants, probed with vertical ray casts over the\ncloth):\n\n* the cloth plane -- the flat sheet the balls rest on -- sits at\n  ``MODEL_FELT_Z`` and is moved to world ``z = 0``, which is where the\n  simulation puts the felt and every ball centre;\n* the cushion noses -- the vertical faces a ball actually bounces off -- are at\n  ``+/- MODEL_NOSE_HALF_X`` and ``+/- MODEL_NOSE_HALF_Y``, so they are scaled\n  onto the simulation's cushion planes (``play_half_x`` / ``play_half_y``).\n\nThe two axes get **different** scale factors (0.922 and 0.943). That is not an\naccident: this model's playing surface is 1.96 x 0.99 m, the scene's is\n1.81 x 0.93 m, and those are not the same shape, because the scene was scaled so\nthat the *balls* are regulation rather than the table (see ``scene_config``).\nForcing one uniform factor would leave the cushions 5-10 mm off the planes the\nsimulation bounces the balls on -- close enough to look like the balls are\nsinking into the cushion at the moment of contact. A 2% anisotropy on a piece of\nfurniture is invisible; a ball 5 mm inside a cushion is not.\n\nWhat is dropped\n---------------\nThe file ships sixteen balls, a triangle rack, a chalk cube and two cue sticks\narranged on and around the table. None of them belong in this shot: the scene\nhas its own four balls under physics, and the rack would sit on the cue ball's\npath. They are hidden rather than deleted, the same way ``import_table`` hides\nthe fifteen balls the shot does not use.\n\nSource: https://sketchfab.com/3d-models/pool-table-billiard-table-with-cues-and-balls\n(Mark Peters, CC-BY-4.0)\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nfrom pathlib import Path\n\nimport bpy\n\nPOOL_TABLE_MODEL_PATH = (\n    _PCVE_ROOT\n    / \"assets\"\n    / \"models\"\n    / \"pool_table_-_billiard_table_with_cues_and_balls.glb\"\n)\n\n# ---------------------------------------------------------- measured off the file\n# Cloth plane. The most common vertex height in the bed mesh, and the height every\n# downward ray between the cushions returns -- the cloth is a single flat sheet.\nMODEL_FELT_Z = 0.795\n# Cushion noses, from ray casts across the cloth: the surface steps from the felt\n# up onto the cushion at exactly these distances from the table's centre.\nMODEL_NOSE_HALF_X = 0.980\nMODEL_NOSE_HALF_Y = 0.495\n\n# The two meshes that are the table. Everything else in the file is a prop.\nTABLE_MESH_SUFFIXES = {\n    \"_PoolTable_MTL_0\": \"pool_table_bed\",\n    \"_PoolTable_MTL_0.001\": \"pool_table_frame\",\n}\n\n\ndef _scale_for(play_half_x: float, play_half_y: float) -> tuple[float, float, float]:\n    \"\"\"Per-axis scale that lands this model's cushion noses on the scene's planes.\n\n    ``z`` takes the mean of the two so the cushions keep their profile: the\n    difference between the horizontal factors is 2%, and splitting it vertically\n    is less visible than picking one axis and squashing the cushion height.\n    \"\"\"\n    sx = play_half_x / MODEL_NOSE_HALF_X\n    sy = play_half_y / MODEL_NOSE_HALF_Y\n    return (sx, sy, (sx + sy) / 2.0)\n\n\n# The one material the table carries. Cloth, rails, apron and legs share it, and\n# it is one 4k atlas, so any adjustment has to be one that suits all of them.\nTABLE_MATERIAL = \"PoolTable_MTL\"\n\n# Grading, applied to the texture rather than baked into it.\n#\n# The atlas is a pale sage cloth. Under the hall's key lamp -- and through AgX,\n# which trades saturation for headroom as a value climbs -- a sample of the cloth\n# comes out (183, 206, 179): 23 levels between green and red is a mint, not a\n# felt. The wood is a grey-brown at similar brightness, so the table as a whole\n# reads as grey plastic while the room around it stays dark and warm.\n#\n# Saturation is the right operator here because it scales the colour that is\n# already there: the cloth gains most of it, the warm wood gains a little and\n# reads as varnished rather than painted, and anything neutral in the atlas\n# (sights, name plate) does not move at all. A multiply would have dragged the\n# wood green, and repainting the atlas is not this scene's business.\nGRADE_SATURATION = 1.55\nGRADE_VALUE = 0.88\n\n# Floor for the roughness the model ships.\n#\n# The frame is varnished and the map has it very smooth: under a 26 W bar lamp\n# 0.6 m above the cloth, the near rail returns two hard, pure-white patches of\n# reflected lamp where a real varnish would return a soft sheen. Clamping the\n# floor to 0.40 keeps the finish glossy -- the highlight is still there and still\n# moves with the camera -- but stops it clipping to white, and it costs the\n# cloth nothing: felt should be matte anyway, and its nap is in the normal map,\n# not in this channel.\nROUGHNESS_FLOOR = 0.40\n\n\ndef grade_table(table: list[bpy.types.Object]) -> None:\n    \"\"\"Grade the cloth's colour and the frame's finish, on the node tree.\n\n    Both go between the model's own maps and the Principled node, so the\n    original maps are untouched and each adjustment is one node to find.\n    \"\"\"\n    done: set[str] = set()\n    for obj in table:\n        for mat in obj.data.materials:\n            if mat is None or not mat.use_nodes or mat.name in done:\n                continue\n            done.add(mat.name)\n            tree = mat.node_tree\n            bsdf = next((n for n in tree.nodes if n.type == \"BSDF_PRINCIPLED\"), None)\n            if bsdf is None:\n                continue\n\n            base = bsdf.inputs[\"Base Color\"]\n            if base.is_linked:\n                source = base.links[0].from_node\n                grade = tree.nodes.new(\"ShaderNodeHueSaturation\")\n                grade.name = \"table_grade\"\n                grade.inputs[\"Saturation\"].default_value = GRADE_SATURATION\n                grade.inputs[\"Value\"].default_value = GRADE_VALUE\n                grade.location = (source.location.x + 220.0, source.location.y)\n                tree.links.new(source.outputs[\"Color\"], grade.inputs[\"Color\"])\n                tree.links.new(grade.outputs[\"Color\"], base)\n\n            rough = bsdf.inputs[\"Roughness\"]\n            if rough.is_linked:\n                link = rough.links[0]\n                clamp = tree.nodes.new(\"ShaderNodeMath\")\n                clamp.name = \"table_roughness_floor\"\n                clamp.operation = \"MAXIMUM\"\n                clamp.inputs[1].default_value = ROUGHNESS_FLOOR\n                clamp.location = (link.from_node.location.x + 220.0,\n                                  link.from_node.location.y - 220.0)\n                tree.links.new(link.from_socket, clamp.inputs[0])\n                tree.links.new(clamp.outputs[0], rough)\n\n\ndef import_table(play_half_x: float, play_half_y: float) -> list[bpy.types.Object]:\n    \"\"\"Import the table, fitted so its felt is world ``z = 0`` and its noses land\n    on ``+/- play_half_x`` / ``+/- play_half_y``.\n\n    Returns the two table meshes, each with its world transform baked into the\n    mesh data and the object left at the origin -- so nothing downstream has to\n    know about the empty hierarchy the file arrived in.\n    \"\"\"\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(POOL_TABLE_MODEL_PATH))\n    imported = [obj for obj in bpy.data.objects if obj not in before]\n\n    table: list[bpy.types.Object] = []\n    for obj in imported:\n        if obj.type != \"MESH\":\n            continue\n        renamed = next(\n            (name for suffix, name in TABLE_MESH_SUFFIXES.items()\n             if obj.name.endswith(suffix)),\n            None,\n        )\n        if renamed is None:\n            # Balls, the rack, the chalk and the cues.\n            obj.hide_viewport = True\n            obj.hide_render = True\n            continue\n        obj.name = renamed\n        table.append(obj)\n    if len(table) != len(TABLE_MESH_SUFFIXES):\n        raise RuntimeError(\n            f\"Expected {len(TABLE_MESH_SUFFIXES)} table meshes in \"\n            f\"{POOL_TABLE_MODEL_PATH.name}, found {len(table)}\"\n        )\n\n    # Drop the empties: the file nests the table under a centimetre-scaled root\n    # and a hundred-scaled group, and every one of those transforms has to end up\n    # in the mesh before the fitting scale can be written into ``obj.scale``.\n    for obj in table:\n        world = obj.matrix_world.copy()\n        obj.parent = None\n        obj.matrix_world = world\n    bpy.ops.object.select_all(action=\"DESELECT\")\n    for obj in table:\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active = table[0]\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n\n    scale = _scale_for(play_half_x, play_half_y)\n    for obj in table:\n        obj.scale = scale\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n\n    # The cloth is the one surface that has to be exact, so the drop is computed\n    # from the measured felt height rather than from the model's own floor.\n    for obj in table:\n        obj.location.z = -MODEL_FELT_Z * scale[2]\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=False)\n    bpy.ops.object.select_all(action=\"DESELECT\")\n\n    grade_table(table)\n    bpy.context.view_layer.update()\n    return table\n", "scene_support.pool_break.wall_decor": "\"\"\"Wall pictures for the pool hall, from the cafe_wall_pictures pack.\n\nThe walls used to carry two prints built out of boxes: a brass frame, a card\nmount and a dark rectangle. At four metres that is a rectangle with a lighter\nrectangle inside it -- no glass, no print, no depth. They were placeholders\nthat had stopped pretending.\n\nThis pack ships three framed prints with proper 2k maps, glass, a moulded\nframe and a shadow gap behind. They cost one import.\n\nScale\n-----\nUnlike the props pack (which is a centimetre FBX that arrives at a tenth of\nits size), this one is authored in metres: each picture measures 488 x 335 x\n13 mm on import, which is a real cafe print and needs no correction factor.\nThe check is the thickness -- 13 mm is a picture frame, and 130 mm would not\nbe.\n\nThe three pictures sit on top of each other in the file\n-----------------------------------------------------\nAll three meshes share one origin and identical bounds: the pack is a set of\ninterchangeable frames, not a composed arrangement. So each one is unparented\nand treated as its own object, and the arrangement is decided here.\n\nSource: https://sketchfab.com/3d-models/cafe-wall-pictures-7016b8389cdc45658bb1399f476fad00\n(Guy in a Poncho, CC-BY-4.0)\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nfrom pathlib import Path\n\nimport bpy\n\nCAFE_MODEL_PATH = (\n    _PCVE_ROOT / \"assets\" / \"models\" / \"cafe_wall_pictures.glb\"\n)\n\nPICTURE_1 = \"wall_picture_1_wall_picture_1_2k_0\"\nPICTURE_2 = \"wall_picture_2_wall_picture_2_2k_0\"\nPICTURE_3 = \"wall_picture_3_wall_picture_3_0\"\n\nPICTURE_MESHES = (PICTURE_1, PICTURE_2, PICTURE_3)\n\n# The pack's three frames are not the same size, and one of them is a portrait:\n# PICTURE_1 is 488 x 335, PICTURE_2 is 428 x 623 (the portrait), PICTURE_3 is\n# 591 x 406 mm. At 0.88 they come out 429 x 295, 377 x 548 and 520 x 357 mm,\n# which is cafe-print size on a 4 m wall. The names do not sort by size -- the\n# portrait is PICTURE_2, not PICTURE_3 -- so check the numbers, not the index.\n#\n# The factor dates from the 25 mm rig, whose top of frame stopped at z = 0.77 m\n# above the felt: the portrait at 1:1 is 623 mm, and at any height clear of the\n# cap rail it broke the top edge. The current 21 mm rig sees up to z = 1.00 m, so\n# 1:1 would fit now -- the set is left at 0.88 because the arrangement was solved\n# against these sizes and nothing about the frame wants them bigger.\nPICTURE_SCALE = 0.88\n\n# The frame's moulding faces model +X and the print sits at the top of that\n# face, so a picture hung with no rotation looks at +X -- i.e. away from the\n# far wall and into the room, which is where the camera is.\nPICTURE_FRONT_AXIS = \"+X\"\n\n\ndef _flatten_alpha(materials) -> None:\n    \"\"\"Turn the pack's blended glass into dithered glass.\n\n    All three materials import with ``alphaMode: BLEND`` and an alpha channel\n    packed into the base texture. In EEVEE a blended surface has no depth\n    sorting of its own, so the glass pane and the print it covers resolve in\n    whatever order the triangles happen to be drawn in -- the prints came out\n    with large white and dark wedges sliced across them, which is what a\n    sorted-by-guess transparency looks like.\n\n    Stochastic alpha (``DITHERED``, which is ``HASHED`` in 4.x terms) keeps the\n    glass but resolves coverage per sample instead of per object, so there is\n    nothing left to sort. At four metres the dither noise is invisible; the\n    wedges were not.\n    \"\"\"\n    for mat in materials:\n        if mat is None:\n            continue\n        if hasattr(mat, \"surface_render_method\"):\n            mat.surface_render_method = \"DITHERED\"\n        if hasattr(mat, \"blend_method\"):\n            mat.blend_method = \"HASHED\"\n\n\ndef import_pictures() -> dict[str, bpy.types.Object]:\n    \"\"\"Import the pack and return its three prints, each standing on its own.\n\n    Every returned object is unparented, has its world transform baked into the\n    mesh data and its origin at the centre of its own bounds -- so hanging it\n    is ``location`` plus a yaw, with no inherited hierarchy to undo.\n    \"\"\"\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(CAFE_MODEL_PATH))\n    imported = [obj for obj in bpy.data.objects if obj not in before]\n\n    kept: dict[str, bpy.types.Object] = {}\n    materials = []\n    for obj in imported:\n        if obj.type != \"MESH\":\n            # The pack's Sketchfab/RootNode empties. They render nothing and\n            # keeping them parented would drag the prints along with them.\n            continue\n        world = obj.matrix_world.copy()\n        obj.parent = None\n        obj.matrix_world = world\n        bpy.ops.object.select_all(action=\"DESELECT\")\n        obj.select_set(True)\n        bpy.context.view_layer.objects.active = obj\n        bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n        obj.scale = (PICTURE_SCALE, PICTURE_SCALE, PICTURE_SCALE)\n        bpy.ops.object.transform_apply(scale=True)\n        bpy.ops.object.origin_set(type=\"ORIGIN_GEOMETRY\", center=\"BOUNDS\")\n        obj.select_set(False)\n        # glTF leaves objects in quaternion mode, where writing rotation_euler\n        # is silently ignored. Everything downstream yaws these objects.\n        obj.rotation_mode = \"XYZ\"\n        kept[obj.name] = obj\n        materials.extend(m for m in obj.data.materials if m is not None)\n    _flatten_alpha(materials)\n    bpy.context.view_layer.update()\n    return kept\n\n\ndef hang(obj: bpy.types.Object, x: float, y: float, z: float,\n         yaw: float = 0.0) -> None:\n    \"\"\"Hang one picture at ``(x, y, z)``, turned ``yaw`` about the vertical.\n\n    ``x`` is the centre of the frame; callers that want the back of the frame\n    against a wall should subtract half the thickness (``obj.dimensions.x``)\n    from the wall plane themselves, because only they know which wall it is.\n    \"\"\"\n    obj.rotation_mode = \"XYZ\"\n    obj.rotation_euler = (0.0, 0.0, yaw)\n    obj.location = (x, y, z)\n\n\ndef back_offset(obj: bpy.types.Object) -> float:\n    \"\"\"Half the frame's thickness, so it can be set back against a wall.\"\"\"\n    return obj.dimensions.x / 2.0\n", "scene_support.pool_break": "\"\"\"Shared support modules for pool_break.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n", "cache_contract": "\"\"\"Compatibility contract for pool-break trajectories and renderer replays.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib\nimport json\nfrom pathlib import Path\n\ndef _scene_directory():\n    scripts_root = _PCVE_ROOT / 'clean_scripts'\n    for candidate in (scripts_root / \"rigid_rigid\" / \"pool_break\", scripts_root / \"pool_break\"):\n        if candidate.is_dir():\n            return candidate\n    raise FileNotFoundError(\"Scene directory not found for pool_break\")\n\n\nCACHE_SCHEMA_VERSION = 4\n\n\ndef signature(parameters):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=parameters)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(data, requested=None):\n    message = (\n        \"Incompatible pool-break physics cache: parameters, geometry or \"\n        \"implementation changed; resimulate first.\"\n    )\n    if data.get(\"schema_version\") != CACHE_SCHEMA_VERSION or data.get(\"scene\") != \"pool_break\":\n        raise ValueError(message)\n    params = data.get(\"simulation_parameters\", {})\n    if data.get(\"simulation_signature\") != signature(params):\n        raise ValueError(message)\n    for name, value in (requested or {}).items():\n        if value is not None and params.get(name) != value:\n            raise ValueError(message + \" Mismatch: \" + name)\n    count = max(2, round(params[\"fps\"] * params[\"duration_sec\"]))\n    if (\n        data.get(\"fps\") != params[\"fps\"]\n        or data.get(\"duration_sec\") != params[\"duration_sec\"]\n        or data.get(\"frame_end\") != count\n        or len(data.get(\"frames\", [])) != count\n    ):\n        raise ValueError(message)\n    for name, value in data.get(\"physics_parameters\", {}).items():\n        if name in params and value != params[name]:\n            raise ValueError(message)\n", "props": "\"\"\"The seating and the bin for the pool hall.\n\nFurniture in this room has been rebuilt twice. First it was primitives -- a\nbench, a side table, a chair and a cabinet, each one a box or two standing on\nlegs. They were enough to say \"room\", but they said it the only way a box can:\nno upholstery, no seat, square edges, a silhouette that reads \"proxy\" the moment\nyou look at it for more than a second.\n\nThen the seating came from ``jayden_miles_individual_modular_props``: two chairs\nwith blue cushions and white frames, and a black bin. Better than boxes, but the\npack is a mobile-game asset -- the chairs are flat-shaded with a single 512 px\nmap, and at four metres their frames are the brightest thing in the frame after\nthe cloth, which pulls the eye off the break.\n\nThe chairs are now ``rustic_chair.glb``: a scanned wooden chair with a 2k map,\nreal joinery at the stretchers and a worn seat. Two copies, because a hall seats\nmore than one person. The bin still comes from the props pack -- a barrel is a\nbarrel, and it is meant to be the black shape in the frame.\n\nScale\n-----\nThe props pack is a Sketchfab export of an FBX whose units are centimetres, and\nSketchfab's root matrix divides by 100 on the way in, so its meshes arrive at a\ntenth of their authored size -- a chair 0.08 m tall. ``PROPS_IMPORT_SCALE`` puts\nthem back. The rustic chair does not need that correction: it arrives at 0.55 x\n0.53 x 0.96 m, which is a chair, so it keeps its own scale.\n\nSource (chairs): https://sketchfab.com/3d-models/rustic-chair (CC-BY-4.0)\nSource (bin): https://sketchfab.com/3d-models/jayden-miles-individual-modular-props-67e7db80574443338eb112125117d5e1\n(jamiles, CC-BY-4.0)\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport math\nfrom pathlib import Path\n\nimport bpy\nfrom mathutils import Vector\n\nPROPS_MODEL_PATH = (\n    _PCVE_ROOT / \"assets\" / \"models\" / \"jayden_miles_individual_modular_props.glb\"\n)\nCHAIR_MODEL_PATH = _PCVE_ROOT / \"assets\" / \"models\" / \"rustic_chair.glb\"\n\n# See the module docstring: the import already divided the authored centimetres\n# by 100, so this factor is what restores them.\nPROPS_IMPORT_SCALE = 10.0\n\nTRASHBIN_MESH = \"Trashbin_Mat_Trashbin_0\"\nKEPT_MESHES = (TRASHBIN_MESH,)\n\n\ndef _flatten(obj: bpy.types.Object, scale: float = 1.0) -> None:\n    \"\"\"Detach ``obj`` from its hierarchy with its world transform baked in.\n\n    After this the object's origin sits at the centre of its own bounds and its\n    mesh is in metres, so placing it means setting ``location`` and turning it --\n    not undoing an inherited hierarchy whose scale is 100 on one level and 0.001\n    on the next.\n    \"\"\"\n    world = obj.matrix_world.copy()\n    obj.parent = None\n    obj.matrix_world = world\n    if scale != 1.0:\n        obj.scale = (\n            obj.scale.x * scale,\n            obj.scale.y * scale,\n            obj.scale.z * scale,\n        )\n    bpy.ops.object.select_all(action=\"DESELECT\")\n    obj.select_set(True)\n    bpy.context.view_layer.objects.active = obj\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n    bpy.ops.object.origin_set(type=\"ORIGIN_GEOMETRY\", center=\"BOUNDS\")\n    obj.select_set(False)\n    # The glTF importer leaves these in quaternion mode, where ``rotation_euler``\n    # is a stale copy of the last quaternion and writing to it does nothing at\n    # all. Everything downstream turns the props by yaw, so switch them to Euler\n    # up front.\n    obj.rotation_mode = \"XYZ\"\n\n\ndef import_props() -> dict[str, bpy.types.Object]:\n    \"\"\"Import the props pack, keep the bin, hide the rest.\n\n    Returns the kept object keyed by mesh name, already scaled to metres.\n    \"\"\"\n    # Remember what was already in the file. The scene is built in pieces --\n    # the table, the room, then these props -- and \"hide everything I did not\n    # keep\" has to mean \"everything this import brought in\", or it hides the\n    # walls and the table as well.\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(PROPS_MODEL_PATH))\n    imported = [obj for obj in bpy.data.objects if obj not in before]\n\n    kept: dict[str, bpy.types.Object] = {}\n    for obj in imported:\n        if obj.type != \"MESH\":\n            continue\n        if obj.name in KEPT_MESHES:\n            _flatten(obj, PROPS_IMPORT_SCALE)\n            kept[obj.name] = obj\n        else:\n            # The pack's own chairs, table and rails: the scene supplies its own.\n            obj.hide_viewport = True\n            obj.hide_render = True\n    bpy.context.view_layer.update()\n    return kept\n\n\ndef import_chairs(count: int = 2) -> list[bpy.types.Object]:\n    \"\"\"Import ``rustic_chair.glb`` and return ``count`` independently placeable chairs.\n\n    One import, then copies: the copies share the mesh data (nothing downstream\n    edits vertices, only object transforms) but each gets its own object, so\n    ``place`` can stand them in different spots and at different angles.\n    \"\"\"\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(CHAIR_MODEL_PATH))\n    imported = [obj for obj in bpy.data.objects if obj not in before]\n    meshes = [obj for obj in imported if obj.type == \"MESH\"]\n    if not meshes:\n        raise RuntimeError(f\"No mesh found in {CHAIR_MODEL_PATH.name}\")\n    for obj in imported:\n        if obj.type != \"MESH\":\n            obj.hide_viewport = True\n            obj.hide_render = True\n\n    chair = meshes[0]\n    _flatten(chair)\n    chair.name = \"rustic_chair\"\n\n    chairs = [chair]\n    for index in range(1, count):\n        copy = chair.copy()\n        copy.name = f\"rustic_chair_{index + 1}\"\n        bpy.context.scene.collection.objects.link(copy)\n        chairs.append(copy)\n    bpy.context.view_layer.update()\n    return chairs\n\n\ndef yaw_facing(dx: float, dy: float) -> float:\n    \"\"\"The yaw that turns a prop's front toward the direction ``(dx, dy)``.\n\n    Both the rustic chair and the pack's bin face model -Y (measured off the\n    meshes: a chair's backrest is the only geometry above seat height, and on\n    the rustic chair it sits on the +Y side; the bin is a barrel and does not\n    care). A Blender Z rotation of ``theta`` sends that front to\n    ``(sin t, -cos t)``, so ``theta = atan2(dx, -dy)`` is the one that points it\n    at ``(dx, dy)``.\n    \"\"\"\n    return math.atan2(dx, -dy)\n\n\ndef drop_to_floor(obj: bpy.types.Object, floor_z: float) -> None:\n    \"\"\"Put the object on the floor without touching its mesh.\n\n    The meshes carry their authored offset in the vertices, so \"on the floor\"\n    is a question about the lowest point of the world-space bounding box, not\n    about the object's origin.\n    \"\"\"\n    bpy.context.view_layer.update()\n    lowest = min((obj.matrix_world @ Vector(corner)).z for corner in obj.bound_box)\n    obj.location.z += floor_z - lowest\n    bpy.context.view_layer.update()\n\n\ndef place(obj: bpy.types.Object, x: float, y: float, yaw: float, floor_z: float) -> None:\n    \"\"\"Move the object to ``(x, y)``, turn it to ``yaw`` and stand it on the floor.\n\n    ``yaw`` is measured the Blender way: 0 rad points the model's front along\n    -Y, and positive yaw turns it counter-clockwise seen from above.\n    \"\"\"\n    obj.rotation_mode = \"XYZ\"\n    obj.rotation_euler = (0.0, 0.0, yaw)\n    obj.location.x = x\n    obj.location.y = y\n    drop_to_floor(obj, floor_z)\n\n\ndef face_towards(obj: bpy.types.Object, x: float, y: float,\n                 target_x: float, target_y: float, floor_z: float) -> None:\n    \"\"\"Stand the object at ``(x, y)`` turned to look at ``(target_x, target_y)``.\"\"\"\n    place(obj, x, y, yaw_facing(target_x - x, target_y - y), floor_z)\n", "runtime_support": "\"\"\"Local runtime discovery; scripts also work in ordinary Python/Blender installs.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport os\nimport sys\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\n_dll_handles = []\nif os.name == \"nt\":\n    directory = Path(sys.prefix) / \"Library/bin\"\n    if directory.exists():\n        _dll_handles.append(os.add_dll_directory(str(directory)))\n\n\ndef python_for(role):\n    sys.path.insert(0, str(ROOT/'clean_scripts'))\n    from pcve_scene_runtime import python_for as resolve_python\n    return resolve_python(role)\n", "scene_config": "\"\"\"Shared geometry and baseline parameters for the pool-break scene.\n\nBoth the PyBullet simulation and the Blender renderer import these constants, so\nthe collision bodies and the visible meshes cannot drift apart and the scene's\nthree exposed controls have exactly one definition.\n\nWorld conventions\n-----------------\n* The table's long axis is **X**. The cue ball breaks from ``+X`` towards\n  ``-X``, so the camera sits behind the cue at ``+X`` and looks down the table.\n* **+Y** is the far side of the table as seen from that camera's default rig\n  (forward ``-X``, up ``+Z`` => screen-right is ``+Y``), which is why a\n  positive ``cue_contact_offset`` reads as \"hit the right side of the apex\n  ball\" rather than as an abstract axis sign.\n* The felt surface is world ``z = 0``; every ball centre sits at ``z = radius``.\n  The imported table model is shifted down by its own felt height so the two\n  frames coincide -- see :func:`model_z_shift`.\n\nWhy the scene is scaled by the ball, not by the table\n-----------------------------------------------------\n``pool_table_animation.glb`` is authored in FBX centimetres: the felt mesh\nmeasures 1200.7 x 621.8 units and every ball mesh has a 18.93-unit radius. A\nreal 57.15 mm ball against that felt would make a 3.6 m table, so the model's\nballs are oversized relative to its cloth. Scaling so the *balls* are\nregulation (``SCENE_SCALE``) instead gives a 1.81 x 0.94 m playing surface --\na compact bar table, which is a real thing -- and keeps every number that the\nphysics cares about (ball/ball contact, cue speed, gravity) in familiar units.\nScaling by the table instead would leave 76 mm balls that visibly do not behave\nlike billiard balls at this camera distance.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nfrom pathlib import Path\n\n# ---------------------------------------------------------------- the model\n\nMODEL_PATH = _PCVE_ROOT / \"assets\" / \"models\" / \"pool_table_animation.glb\"\n\n# Measured off the model: every ball mesh is a sphere of this radius, the felt\n# mesh is a flat sheet at this height, and the cushion nose sits at the felt\n# edge (the vertex scan put it within 1.5 units of the felt bound).\nMODEL_BALL_RADIUS_UNITS = 18.9315\nMODEL_FELT_TOP_Z_UNITS = 100.012\nMODEL_PLAY_HALF_X_UNITS = 598.9\nMODEL_PLAY_HALF_Y_UNITS = 309.4\nMODEL_FLOOR_Z_UNITS = -363.94        # bottom of the legs, for the visual floor\n\n# Regulation pool ball: 57.15 mm diameter.\nBALL_RADIUS = 0.028575\nSCENE_SCALE = BALL_RADIUS / MODEL_BALL_RADIUS_UNITS\n\nPLAY_HALF_X = MODEL_PLAY_HALF_X_UNITS * SCENE_SCALE      # 0.904 m\nPLAY_HALF_Y = MODEL_PLAY_HALF_Y_UNITS * SCENE_SCALE      # 0.467 m\nMODEL_FLOOR_Z = MODEL_FLOOR_Z_UNITS * SCENE_SCALE\n\n\ndef model_z_shift() -> float:\n    \"\"\"How far to drop the imported table so its felt lands on world ``z = 0``.\"\"\"\n    return MODEL_FELT_TOP_Z_UNITS * SCENE_SCALE\n\n\n# Which mesh in the GLB plays which part. The file ships a full rack of\n# fifteen numbered balls plus a white cue ball and two cue sticks; the scene\n# only uses four of them and hides the rest, exactly the way\n# ``pool_collision`` hides the balls its shot does not use.\nCUE_BALL_MESH = \"Ball Clube_10 - Default_0\"\nAPEX_BALL_MESH = \"Ball1_01 - Default_0\"\nLEFT_BALL_MESH = \"Ball2_Material #158_0\"\nRIGHT_BALL_MESH = \"Ball3_Material #157_0\"\n# Hidden on import: the rest of the rack, and both sticks (this scene drives\n# the cue ball kinematically at frame 1 rather than animating a stick).\nUNUSED_BALL_PREFIX = \"Ball\"\nCUE_STICK_PREFIXES = (\"Cue stick\", \"Cue stick2\")\n\n# ----------------------------------------------------------------- the rack\n# The foot spot is the middle of the far half of the table, which is where a\n# rack is set in every published rule set.\nFOOT_SPOT_X = -PLAY_HALF_X / 2.0\n# Cue ball starts behind the head string and drives 1.05 m up the table.\nCUE_START_X = 0.60\n# A 0.5 mm air gap between the racked balls. Placing them exactly touching\n# makes Bullet resolve an initial overlap with a separation impulse on frame 1,\n# which pushes the rack apart before the cue ball has moved.\nRACK_GAP = 0.0005\n\n\ndef rack_centres() -> dict[str, tuple[float, float]]:\n    \"\"\"Where the three racked balls sit, in the table plane.\n\n    An equilateral triangle pointing at the cue ball: the apex on the foot\n    spot, the other two one centre-to-centre distance behind it. The apex is\n    therefore wedged between the two rear balls, which is what turns a cue-ball\n    impact into a break instead of into a single ball rolling away from an\n    untouched pair.\n\n    The rear pair sits at ``(-d * sqrt(3)/2, +/- d/2)`` relative to the apex --\n    half a spacing to either side, three quarters of a spacing back. That is the\n    first three balls of a real rack: the apex angle seen from the cue ball is\n    60 degrees, so each rear ball sits 30 degrees off the cue's line, and all\n    three pairs are one full spacing apart. Getting this the wrong way round\n    (rear pair at ``(-d/2, +/- d * sqrt(3)/2)``) still touches the apex but\n    leaves the two rear balls 1.73 spacings apart with a hole between them: a\n    flat 120-degree wedge that no rack has ever looked like, and the \"triangle\"\n    reads as two balls flanking a third from a distance.\n    \"\"\"\n    d = 2.0 * BALL_RADIUS + RACK_GAP\n    back = d * 0.8660254037844386\n    across = d * 0.5\n    return {\n        \"apex_ball\": (FOOT_SPOT_X, 0.0),\n        \"right_ball\": (FOOT_SPOT_X - back, +across),\n        \"left_ball\": (FOOT_SPOT_X - back, -across),\n    }\n\n\n# ---------------------------------------------------------------- physics\n\n# The three controls the benchmark exposes.\nBASELINE_PHYSICS = {\n    # A medium break: about 3.6 m/s of cue-ball speed. On a 1.8 m table this\n    # carries the cue ball 1.05 m to the rack in a quarter of a second and\n    # spreads the triangle to the cushions inside the clip.\n    \"cue_speed\": 3.6,            # m/s\n    # Signed lateral offset of the cue ball's line of travel from the apex\n    # ball's centre. + is the apex ball's right side (screen-right); +/-\n    # one ball radius is a half-ball hit, 2 radii is a clean miss.\n    #\n    # Deliberately not 0. A dead-centre hit is a stun shot: the cue ball comes\n    # straight back down its own line (+/-180 degrees) and the rack opens with\n    # perfect mirror symmetry, which no real break does and which makes the\n    # shot look like a diagram. 3 mm is 0.05 radii -- invisible at this camera\n    # distance -- but it is already enough to break the symmetry: the cue ball\n    # leaves at 157 degrees instead of coming straight back, and the apex ball\n    # is nudged to one side.\n    \"cue_contact_offset\": 0.003,  # m\n    \"cue_mass\": 0.17,            # kg -- regulation ball\n}\n\n# Everything an edit must NOT move, so a single-variable edit stays single.\nFIXED_PHYSICS = {\n    \"object_mass\": 0.17,\n    # Bullet multiplies the two bodies' coefficients, so the pair that matters\n    # is 0.25 * 0.12 = 0.03. This pair governs the *sliding* phase only -- it is\n    # what stops the cue ball skidding and gets it rolling, and it is kept low\n    # because at 0.6/0.9 the cue ball loses 5.3 m/s^2 and stops a third of the\n    # way to the rack. The loss that lasts, cloth drag, is ``BALL_ROLL_DECEL``.\n    \"ball_friction\": 0.25,\n    \"felt_friction\": 0.12,\n    # Left at zero on purpose. Bullet's rolling-friction constraint on a sphere\n    # does not give a rolling ball a constant drag -- it instead cancels the\n    # spin the contact friction is trying to build, so the ball slides the whole\n    # way at the full lateral coefficient. Cloth drag therefore lives in the\n    # lateral pair above, and the visible roll is reconstructed from each ball's\n    # path by ``simulate_pool_break.rolling_quaternions``.\n    \"ball_rolling_friction\": 0.0,\n    \"ball_spinning_friction\": 0.0,\n    \"ball_restitution\": 0.93,        # ball <-> ball reads 0.93 * 0.93 = 0.86\n    \"felt_restitution\": 0.10,\n    \"cushion_friction\": 0.30,\n    \"cushion_restitution\": 0.72,\n    \"gravity_z\": -9.81,\n}\n\n# Cloth drag, applied explicitly as a constant deceleration (m/s^2).\n#\n# Coulomb friction alone cannot stop a ball: once it rolls without slipping the\n# contact patch is stationary, the friction force drops to zero and a rigid\n# sphere on a rigid plane coasts forever. Real cloth dissipates through fibre\n# deformation and the ball's own hysteresis, which Bullet does not model, and\n# its ``rollingFriction`` term is not usable here (see above -- it fights the\n# spin instead of damping it). So the drag is integrated by hand, and without it\n# the clip ended with four balls still travelling at 0.5-1.2 m/s after five\n# cushion bounces, the triangle width oscillating between 70 mm and 570 mm from\n# frame to frame -- a pinball table, not a break.\n#\n# The value is the physical one. A ball rolling on worsted cloth decelerates at\n# 0.2-0.35 m/s^2 (rolling resistance coefficient 0.02-0.035); 0.30 is the fast\n# end of that band, which is what a brushed worsted cloth under a hard break\n# behaves like. Note that the total loss is not this number alone: while a ball\n# is still sliding it also pays the felt's Coulomb term (``ball_friction`` *\n# ``felt_friction`` * g = 0.29 m/s^2), so the hand-integrated drag is the\n# rolling-phase loss only.\n#\n# This used to be 0.8 to make a 2.5 s clip settle, and 0.8 is what a viewer\n# reads as wrong: it is 3x the real figure, and it stopped every ball by 1.9 s.\n# The constraint that forced it was clip length, and clip length is now 4 s\n# (``BASELINE_RENDER``), so the compromise is gone. At 0.30 the same break runs\n# 2.4 m of path per wing ball instead of 1.2 m -- a wing ball reaches the corner,\n# comes off the end cushion and carries back across the table -- and the last\n# ball dies at 3.96 s, one frame before the end.\n#\n# The two numbers are coupled: shortening the clip below ~3.8 s puts the\n# settling back in the cut-off, and at 2.5 s the two wing balls are still\n# running at 0.39 and 0.48 m/s when the clip ends.\nBALL_ROLL_DECEL = 0.30\n\n# Cushion nose height is 63.5 % of a ball diameter in every table spec.\nCUSHION_HEIGHT = 0.0363\nCUSHION_THICKNESS = 0.05\n# 96 substeps at 24 fps is a 0.43 ms step. The cue ball covers 1.5 mm per\n# substep at the default speed, which is the point: at 48 substeps a fast\n# contact resolves with about 3 mm of penetration on a 28.6 mm radius and the\n# rack visibly pops apart instead of being struck.\nSUBSTEPS_PER_FRAME = 96\n\n# ---------------------------------------------------------------- baseline\n\nBASELINE_RENDER = {\n    \"fps\": 24,\n    # Long enough for the break to finish on its own at the physical cloth\n    # drag: the last ball dies at 3.96 s. A 2.5 s clip (the old default) only\n    # fitted because ``BALL_ROLL_DECEL`` was inflated to stop everything early.\n    \"duration_sec\": 4.0,\n    # Same size every other rigid-body suite in this repo renders at.\n    \"resolution\": (960, 540),\n    \"samples\": 48,\n    \"camera_mode\": \"break\",\n}\n", "table_model": "\"\"\"The hall's pool table, imported from its own model.\n\nWhy this exists\n---------------\nThe scene used to draw its table out of ``pool_table_animation.glb``, the same\nfile that supplies the four balls. That file is a low-poly game asset: the cloth\nis a single flat sheet, the rails are boxes with the corner pockets cut into\nthem by hand, and the apron is four boards. It was enough to hold the physics,\nbut at 1.5 m from the camera the cloth has no nap, the pockets have no throats\nand the frame has no joinery -- the table reads as a green tray with cushions.\n\nThis module brings in a proper billiard table (felt, cushions, leather pockets,\nturned legs, 4k maps) and fits it to the geometry the simulation already uses,\nso the ball trajectories stay valid. The physics is not touched: the balls are\nstill the meshes from ``pool_table_animation.glb`` and still keyed from the same\nPyBullet run. Only the table under them changes.\n\nFitting it to the simulation\n----------------------------\nEverything the shot cares about is measured off the imported mesh rather than\nguessed (see the ``MODEL_*`` constants, probed with vertical ray casts over the\ncloth):\n\n* the cloth plane -- the flat sheet the balls rest on -- sits at\n  ``MODEL_FELT_Z`` and is moved to world ``z = 0``, which is where the\n  simulation puts the felt and every ball centre;\n* the cushion noses -- the vertical faces a ball actually bounces off -- are at\n  ``+/- MODEL_NOSE_HALF_X`` and ``+/- MODEL_NOSE_HALF_Y``, so they are scaled\n  onto the simulation's cushion planes (``play_half_x`` / ``play_half_y``).\n\nThe two axes get **different** scale factors (0.922 and 0.943). That is not an\naccident: this model's playing surface is 1.96 x 0.99 m, the scene's is\n1.81 x 0.93 m, and those are not the same shape, because the scene was scaled so\nthat the *balls* are regulation rather than the table (see ``scene_config``).\nForcing one uniform factor would leave the cushions 5-10 mm off the planes the\nsimulation bounces the balls on -- close enough to look like the balls are\nsinking into the cushion at the moment of contact. A 2% anisotropy on a piece of\nfurniture is invisible; a ball 5 mm inside a cushion is not.\n\nWhat is dropped\n---------------\nThe file ships sixteen balls, a triangle rack, a chalk cube and two cue sticks\narranged on and around the table. None of them belong in this shot: the scene\nhas its own four balls under physics, and the rack would sit on the cue ball's\npath. They are hidden rather than deleted, the same way ``import_table`` hides\nthe fifteen balls the shot does not use.\n\nSource: https://sketchfab.com/3d-models/pool-table-billiard-table-with-cues-and-balls\n(Mark Peters, CC-BY-4.0)\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nfrom pathlib import Path\n\nimport bpy\n\nPOOL_TABLE_MODEL_PATH = (\n    _PCVE_ROOT\n    / \"assets\"\n    / \"models\"\n    / \"pool_table_-_billiard_table_with_cues_and_balls.glb\"\n)\n\n# ---------------------------------------------------------- measured off the file\n# Cloth plane. The most common vertex height in the bed mesh, and the height every\n# downward ray between the cushions returns -- the cloth is a single flat sheet.\nMODEL_FELT_Z = 0.795\n# Cushion noses, from ray casts across the cloth: the surface steps from the felt\n# up onto the cushion at exactly these distances from the table's centre.\nMODEL_NOSE_HALF_X = 0.980\nMODEL_NOSE_HALF_Y = 0.495\n\n# The two meshes that are the table. Everything else in the file is a prop.\nTABLE_MESH_SUFFIXES = {\n    \"_PoolTable_MTL_0\": \"pool_table_bed\",\n    \"_PoolTable_MTL_0.001\": \"pool_table_frame\",\n}\n\n\ndef _scale_for(play_half_x: float, play_half_y: float) -> tuple[float, float, float]:\n    \"\"\"Per-axis scale that lands this model's cushion noses on the scene's planes.\n\n    ``z`` takes the mean of the two so the cushions keep their profile: the\n    difference between the horizontal factors is 2%, and splitting it vertically\n    is less visible than picking one axis and squashing the cushion height.\n    \"\"\"\n    sx = play_half_x / MODEL_NOSE_HALF_X\n    sy = play_half_y / MODEL_NOSE_HALF_Y\n    return (sx, sy, (sx + sy) / 2.0)\n\n\n# The one material the table carries. Cloth, rails, apron and legs share it, and\n# it is one 4k atlas, so any adjustment has to be one that suits all of them.\nTABLE_MATERIAL = \"PoolTable_MTL\"\n\n# Grading, applied to the texture rather than baked into it.\n#\n# The atlas is a pale sage cloth. Under the hall's key lamp -- and through AgX,\n# which trades saturation for headroom as a value climbs -- a sample of the cloth\n# comes out (183, 206, 179): 23 levels between green and red is a mint, not a\n# felt. The wood is a grey-brown at similar brightness, so the table as a whole\n# reads as grey plastic while the room around it stays dark and warm.\n#\n# Saturation is the right operator here because it scales the colour that is\n# already there: the cloth gains most of it, the warm wood gains a little and\n# reads as varnished rather than painted, and anything neutral in the atlas\n# (sights, name plate) does not move at all. A multiply would have dragged the\n# wood green, and repainting the atlas is not this scene's business.\nGRADE_SATURATION = 1.55\nGRADE_VALUE = 0.88\n\n# Floor for the roughness the model ships.\n#\n# The frame is varnished and the map has it very smooth: under a 26 W bar lamp\n# 0.6 m above the cloth, the near rail returns two hard, pure-white patches of\n# reflected lamp where a real varnish would return a soft sheen. Clamping the\n# floor to 0.40 keeps the finish glossy -- the highlight is still there and still\n# moves with the camera -- but stops it clipping to white, and it costs the\n# cloth nothing: felt should be matte anyway, and its nap is in the normal map,\n# not in this channel.\nROUGHNESS_FLOOR = 0.40\n\n\ndef grade_table(table: list[bpy.types.Object]) -> None:\n    \"\"\"Grade the cloth's colour and the frame's finish, on the node tree.\n\n    Both go between the model's own maps and the Principled node, so the\n    original maps are untouched and each adjustment is one node to find.\n    \"\"\"\n    done: set[str] = set()\n    for obj in table:\n        for mat in obj.data.materials:\n            if mat is None or not mat.use_nodes or mat.name in done:\n                continue\n            done.add(mat.name)\n            tree = mat.node_tree\n            bsdf = next((n for n in tree.nodes if n.type == \"BSDF_PRINCIPLED\"), None)\n            if bsdf is None:\n                continue\n\n            base = bsdf.inputs[\"Base Color\"]\n            if base.is_linked:\n                source = base.links[0].from_node\n                grade = tree.nodes.new(\"ShaderNodeHueSaturation\")\n                grade.name = \"table_grade\"\n                grade.inputs[\"Saturation\"].default_value = GRADE_SATURATION\n                grade.inputs[\"Value\"].default_value = GRADE_VALUE\n                grade.location = (source.location.x + 220.0, source.location.y)\n                tree.links.new(source.outputs[\"Color\"], grade.inputs[\"Color\"])\n                tree.links.new(grade.outputs[\"Color\"], base)\n\n            rough = bsdf.inputs[\"Roughness\"]\n            if rough.is_linked:\n                link = rough.links[0]\n                clamp = tree.nodes.new(\"ShaderNodeMath\")\n                clamp.name = \"table_roughness_floor\"\n                clamp.operation = \"MAXIMUM\"\n                clamp.inputs[1].default_value = ROUGHNESS_FLOOR\n                clamp.location = (link.from_node.location.x + 220.0,\n                                  link.from_node.location.y - 220.0)\n                tree.links.new(link.from_socket, clamp.inputs[0])\n                tree.links.new(clamp.outputs[0], rough)\n\n\ndef import_table(play_half_x: float, play_half_y: float) -> list[bpy.types.Object]:\n    \"\"\"Import the table, fitted so its felt is world ``z = 0`` and its noses land\n    on ``+/- play_half_x`` / ``+/- play_half_y``.\n\n    Returns the two table meshes, each with its world transform baked into the\n    mesh data and the object left at the origin -- so nothing downstream has to\n    know about the empty hierarchy the file arrived in.\n    \"\"\"\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(POOL_TABLE_MODEL_PATH))\n    imported = [obj for obj in bpy.data.objects if obj not in before]\n\n    table: list[bpy.types.Object] = []\n    for obj in imported:\n        if obj.type != \"MESH\":\n            continue\n        renamed = next(\n            (name for suffix, name in TABLE_MESH_SUFFIXES.items()\n             if obj.name.endswith(suffix)),\n            None,\n        )\n        if renamed is None:\n            # Balls, the rack, the chalk and the cues.\n            obj.hide_viewport = True\n            obj.hide_render = True\n            continue\n        obj.name = renamed\n        table.append(obj)\n    if len(table) != len(TABLE_MESH_SUFFIXES):\n        raise RuntimeError(\n            f\"Expected {len(TABLE_MESH_SUFFIXES)} table meshes in \"\n            f\"{POOL_TABLE_MODEL_PATH.name}, found {len(table)}\"\n        )\n\n    # Drop the empties: the file nests the table under a centimetre-scaled root\n    # and a hundred-scaled group, and every one of those transforms has to end up\n    # in the mesh before the fitting scale can be written into ``obj.scale``.\n    for obj in table:\n        world = obj.matrix_world.copy()\n        obj.parent = None\n        obj.matrix_world = world\n    bpy.ops.object.select_all(action=\"DESELECT\")\n    for obj in table:\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active = table[0]\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n\n    scale = _scale_for(play_half_x, play_half_y)\n    for obj in table:\n        obj.scale = scale\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n\n    # The cloth is the one surface that has to be exact, so the drop is computed\n    # from the measured felt height rather than from the model's own floor.\n    for obj in table:\n        obj.location.z = -MODEL_FELT_Z * scale[2]\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=False)\n    bpy.ops.object.select_all(action=\"DESELECT\")\n\n    grade_table(table)\n    bpy.context.view_layer.update()\n    return table\n", "wall_decor": "\"\"\"Wall pictures for the pool hall, from the cafe_wall_pictures pack.\n\nThe walls used to carry two prints built out of boxes: a brass frame, a card\nmount and a dark rectangle. At four metres that is a rectangle with a lighter\nrectangle inside it -- no glass, no print, no depth. They were placeholders\nthat had stopped pretending.\n\nThis pack ships three framed prints with proper 2k maps, glass, a moulded\nframe and a shadow gap behind. They cost one import.\n\nScale\n-----\nUnlike the props pack (which is a centimetre FBX that arrives at a tenth of\nits size), this one is authored in metres: each picture measures 488 x 335 x\n13 mm on import, which is a real cafe print and needs no correction factor.\nThe check is the thickness -- 13 mm is a picture frame, and 130 mm would not\nbe.\n\nThe three pictures sit on top of each other in the file\n-----------------------------------------------------\nAll three meshes share one origin and identical bounds: the pack is a set of\ninterchangeable frames, not a composed arrangement. So each one is unparented\nand treated as its own object, and the arrangement is decided here.\n\nSource: https://sketchfab.com/3d-models/cafe-wall-pictures-7016b8389cdc45658bb1399f476fad00\n(Guy in a Poncho, CC-BY-4.0)\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nfrom pathlib import Path\n\nimport bpy\n\nCAFE_MODEL_PATH = (\n    _PCVE_ROOT / \"assets\" / \"models\" / \"cafe_wall_pictures.glb\"\n)\n\nPICTURE_1 = \"wall_picture_1_wall_picture_1_2k_0\"\nPICTURE_2 = \"wall_picture_2_wall_picture_2_2k_0\"\nPICTURE_3 = \"wall_picture_3_wall_picture_3_0\"\n\nPICTURE_MESHES = (PICTURE_1, PICTURE_2, PICTURE_3)\n\n# The pack's three frames are not the same size, and one of them is a portrait:\n# PICTURE_1 is 488 x 335, PICTURE_2 is 428 x 623 (the portrait), PICTURE_3 is\n# 591 x 406 mm. At 0.88 they come out 429 x 295, 377 x 548 and 520 x 357 mm,\n# which is cafe-print size on a 4 m wall. The names do not sort by size -- the\n# portrait is PICTURE_2, not PICTURE_3 -- so check the numbers, not the index.\n#\n# The factor dates from the 25 mm rig, whose top of frame stopped at z = 0.77 m\n# above the felt: the portrait at 1:1 is 623 mm, and at any height clear of the\n# cap rail it broke the top edge. The current 21 mm rig sees up to z = 1.00 m, so\n# 1:1 would fit now -- the set is left at 0.88 because the arrangement was solved\n# against these sizes and nothing about the frame wants them bigger.\nPICTURE_SCALE = 0.88\n\n# The frame's moulding faces model +X and the print sits at the top of that\n# face, so a picture hung with no rotation looks at +X -- i.e. away from the\n# far wall and into the room, which is where the camera is.\nPICTURE_FRONT_AXIS = \"+X\"\n\n\ndef _flatten_alpha(materials) -> None:\n    \"\"\"Turn the pack's blended glass into dithered glass.\n\n    All three materials import with ``alphaMode: BLEND`` and an alpha channel\n    packed into the base texture. In EEVEE a blended surface has no depth\n    sorting of its own, so the glass pane and the print it covers resolve in\n    whatever order the triangles happen to be drawn in -- the prints came out\n    with large white and dark wedges sliced across them, which is what a\n    sorted-by-guess transparency looks like.\n\n    Stochastic alpha (``DITHERED``, which is ``HASHED`` in 4.x terms) keeps the\n    glass but resolves coverage per sample instead of per object, so there is\n    nothing left to sort. At four metres the dither noise is invisible; the\n    wedges were not.\n    \"\"\"\n    for mat in materials:\n        if mat is None:\n            continue\n        if hasattr(mat, \"surface_render_method\"):\n            mat.surface_render_method = \"DITHERED\"\n        if hasattr(mat, \"blend_method\"):\n            mat.blend_method = \"HASHED\"\n\n\ndef import_pictures() -> dict[str, bpy.types.Object]:\n    \"\"\"Import the pack and return its three prints, each standing on its own.\n\n    Every returned object is unparented, has its world transform baked into the\n    mesh data and its origin at the centre of its own bounds -- so hanging it\n    is ``location`` plus a yaw, with no inherited hierarchy to undo.\n    \"\"\"\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(CAFE_MODEL_PATH))\n    imported = [obj for obj in bpy.data.objects if obj not in before]\n\n    kept: dict[str, bpy.types.Object] = {}\n    materials = []\n    for obj in imported:\n        if obj.type != \"MESH\":\n            # The pack's Sketchfab/RootNode empties. They render nothing and\n            # keeping them parented would drag the prints along with them.\n            continue\n        world = obj.matrix_world.copy()\n        obj.parent = None\n        obj.matrix_world = world\n        bpy.ops.object.select_all(action=\"DESELECT\")\n        obj.select_set(True)\n        bpy.context.view_layer.objects.active = obj\n        bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n        obj.scale = (PICTURE_SCALE, PICTURE_SCALE, PICTURE_SCALE)\n        bpy.ops.object.transform_apply(scale=True)\n        bpy.ops.object.origin_set(type=\"ORIGIN_GEOMETRY\", center=\"BOUNDS\")\n        obj.select_set(False)\n        # glTF leaves objects in quaternion mode, where writing rotation_euler\n        # is silently ignored. Everything downstream yaws these objects.\n        obj.rotation_mode = \"XYZ\"\n        kept[obj.name] = obj\n        materials.extend(m for m in obj.data.materials if m is not None)\n    _flatten_alpha(materials)\n    bpy.context.view_layer.update()\n    return kept\n\n\ndef hang(obj: bpy.types.Object, x: float, y: float, z: float,\n         yaw: float = 0.0) -> None:\n    \"\"\"Hang one picture at ``(x, y, z)``, turned ``yaw`` about the vertical.\n\n    ``x`` is the centre of the frame; callers that want the back of the frame\n    against a wall should subtract half the thickness (``obj.dimensions.x``)\n    from the wall plane themselves, because only they know which wall it is.\n    \"\"\"\n    obj.rotation_mode = \"XYZ\"\n    obj.rotation_euler = (0.0, 0.0, yaw)\n    obj.location = (x, y, z)\n\n\ndef back_offset(obj: bpy.types.Object) -> float:\n    \"\"\"Half the frame's thickness, so it can be set back against a wall.\"\"\"\n    return obj.dimensions.x / 2.0\n", "pool_break.cache_contract": "\"\"\"Compatibility contract for pool-break trajectories and renderer replays.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib\nimport json\nfrom pathlib import Path\n\ndef _scene_directory():\n    scripts_root = _PCVE_ROOT / 'clean_scripts'\n    for candidate in (scripts_root / \"rigid_rigid\" / \"pool_break\", scripts_root / \"pool_break\"):\n        if candidate.is_dir():\n            return candidate\n    raise FileNotFoundError(\"Scene directory not found for pool_break\")\n\n\nCACHE_SCHEMA_VERSION = 4\n\n\ndef signature(parameters):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=parameters)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(data, requested=None):\n    message = (\n        \"Incompatible pool-break physics cache: parameters, geometry or \"\n        \"implementation changed; resimulate first.\"\n    )\n    if data.get(\"schema_version\") != CACHE_SCHEMA_VERSION or data.get(\"scene\") != \"pool_break\":\n        raise ValueError(message)\n    params = data.get(\"simulation_parameters\", {})\n    if data.get(\"simulation_signature\") != signature(params):\n        raise ValueError(message)\n    for name, value in (requested or {}).items():\n        if value is not None and params.get(name) != value:\n            raise ValueError(message + \" Mismatch: \" + name)\n    count = max(2, round(params[\"fps\"] * params[\"duration_sec\"]))\n    if (\n        data.get(\"fps\") != params[\"fps\"]\n        or data.get(\"duration_sec\") != params[\"duration_sec\"]\n        or data.get(\"frame_end\") != count\n        or len(data.get(\"frames\", [])) != count\n    ):\n        raise ValueError(message)\n    for name, value in data.get(\"physics_parameters\", {}).items():\n        if name in params and value != params[name]:\n            raise ValueError(message)\n", "pool_break.props": "\"\"\"The seating and the bin for the pool hall.\n\nFurniture in this room has been rebuilt twice. First it was primitives -- a\nbench, a side table, a chair and a cabinet, each one a box or two standing on\nlegs. They were enough to say \"room\", but they said it the only way a box can:\nno upholstery, no seat, square edges, a silhouette that reads \"proxy\" the moment\nyou look at it for more than a second.\n\nThen the seating came from ``jayden_miles_individual_modular_props``: two chairs\nwith blue cushions and white frames, and a black bin. Better than boxes, but the\npack is a mobile-game asset -- the chairs are flat-shaded with a single 512 px\nmap, and at four metres their frames are the brightest thing in the frame after\nthe cloth, which pulls the eye off the break.\n\nThe chairs are now ``rustic_chair.glb``: a scanned wooden chair with a 2k map,\nreal joinery at the stretchers and a worn seat. Two copies, because a hall seats\nmore than one person. The bin still comes from the props pack -- a barrel is a\nbarrel, and it is meant to be the black shape in the frame.\n\nScale\n-----\nThe props pack is a Sketchfab export of an FBX whose units are centimetres, and\nSketchfab's root matrix divides by 100 on the way in, so its meshes arrive at a\ntenth of their authored size -- a chair 0.08 m tall. ``PROPS_IMPORT_SCALE`` puts\nthem back. The rustic chair does not need that correction: it arrives at 0.55 x\n0.53 x 0.96 m, which is a chair, so it keeps its own scale.\n\nSource (chairs): https://sketchfab.com/3d-models/rustic-chair (CC-BY-4.0)\nSource (bin): https://sketchfab.com/3d-models/jayden-miles-individual-modular-props-67e7db80574443338eb112125117d5e1\n(jamiles, CC-BY-4.0)\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport math\nfrom pathlib import Path\n\nimport bpy\nfrom mathutils import Vector\n\nPROPS_MODEL_PATH = (\n    _PCVE_ROOT / \"assets\" / \"models\" / \"jayden_miles_individual_modular_props.glb\"\n)\nCHAIR_MODEL_PATH = _PCVE_ROOT / \"assets\" / \"models\" / \"rustic_chair.glb\"\n\n# See the module docstring: the import already divided the authored centimetres\n# by 100, so this factor is what restores them.\nPROPS_IMPORT_SCALE = 10.0\n\nTRASHBIN_MESH = \"Trashbin_Mat_Trashbin_0\"\nKEPT_MESHES = (TRASHBIN_MESH,)\n\n\ndef _flatten(obj: bpy.types.Object, scale: float = 1.0) -> None:\n    \"\"\"Detach ``obj`` from its hierarchy with its world transform baked in.\n\n    After this the object's origin sits at the centre of its own bounds and its\n    mesh is in metres, so placing it means setting ``location`` and turning it --\n    not undoing an inherited hierarchy whose scale is 100 on one level and 0.001\n    on the next.\n    \"\"\"\n    world = obj.matrix_world.copy()\n    obj.parent = None\n    obj.matrix_world = world\n    if scale != 1.0:\n        obj.scale = (\n            obj.scale.x * scale,\n            obj.scale.y * scale,\n            obj.scale.z * scale,\n        )\n    bpy.ops.object.select_all(action=\"DESELECT\")\n    obj.select_set(True)\n    bpy.context.view_layer.objects.active = obj\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n    bpy.ops.object.origin_set(type=\"ORIGIN_GEOMETRY\", center=\"BOUNDS\")\n    obj.select_set(False)\n    # The glTF importer leaves these in quaternion mode, where ``rotation_euler``\n    # is a stale copy of the last quaternion and writing to it does nothing at\n    # all. Everything downstream turns the props by yaw, so switch them to Euler\n    # up front.\n    obj.rotation_mode = \"XYZ\"\n\n\ndef import_props() -> dict[str, bpy.types.Object]:\n    \"\"\"Import the props pack, keep the bin, hide the rest.\n\n    Returns the kept object keyed by mesh name, already scaled to metres.\n    \"\"\"\n    # Remember what was already in the file. The scene is built in pieces --\n    # the table, the room, then these props -- and \"hide everything I did not\n    # keep\" has to mean \"everything this import brought in\", or it hides the\n    # walls and the table as well.\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(PROPS_MODEL_PATH))\n    imported = [obj for obj in bpy.data.objects if obj not in before]\n\n    kept: dict[str, bpy.types.Object] = {}\n    for obj in imported:\n        if obj.type != \"MESH\":\n            continue\n        if obj.name in KEPT_MESHES:\n            _flatten(obj, PROPS_IMPORT_SCALE)\n            kept[obj.name] = obj\n        else:\n            # The pack's own chairs, table and rails: the scene supplies its own.\n            obj.hide_viewport = True\n            obj.hide_render = True\n    bpy.context.view_layer.update()\n    return kept\n\n\ndef import_chairs(count: int = 2) -> list[bpy.types.Object]:\n    \"\"\"Import ``rustic_chair.glb`` and return ``count`` independently placeable chairs.\n\n    One import, then copies: the copies share the mesh data (nothing downstream\n    edits vertices, only object transforms) but each gets its own object, so\n    ``place`` can stand them in different spots and at different angles.\n    \"\"\"\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(CHAIR_MODEL_PATH))\n    imported = [obj for obj in bpy.data.objects if obj not in before]\n    meshes = [obj for obj in imported if obj.type == \"MESH\"]\n    if not meshes:\n        raise RuntimeError(f\"No mesh found in {CHAIR_MODEL_PATH.name}\")\n    for obj in imported:\n        if obj.type != \"MESH\":\n            obj.hide_viewport = True\n            obj.hide_render = True\n\n    chair = meshes[0]\n    _flatten(chair)\n    chair.name = \"rustic_chair\"\n\n    chairs = [chair]\n    for index in range(1, count):\n        copy = chair.copy()\n        copy.name = f\"rustic_chair_{index + 1}\"\n        bpy.context.scene.collection.objects.link(copy)\n        chairs.append(copy)\n    bpy.context.view_layer.update()\n    return chairs\n\n\ndef yaw_facing(dx: float, dy: float) -> float:\n    \"\"\"The yaw that turns a prop's front toward the direction ``(dx, dy)``.\n\n    Both the rustic chair and the pack's bin face model -Y (measured off the\n    meshes: a chair's backrest is the only geometry above seat height, and on\n    the rustic chair it sits on the +Y side; the bin is a barrel and does not\n    care). A Blender Z rotation of ``theta`` sends that front to\n    ``(sin t, -cos t)``, so ``theta = atan2(dx, -dy)`` is the one that points it\n    at ``(dx, dy)``.\n    \"\"\"\n    return math.atan2(dx, -dy)\n\n\ndef drop_to_floor(obj: bpy.types.Object, floor_z: float) -> None:\n    \"\"\"Put the object on the floor without touching its mesh.\n\n    The meshes carry their authored offset in the vertices, so \"on the floor\"\n    is a question about the lowest point of the world-space bounding box, not\n    about the object's origin.\n    \"\"\"\n    bpy.context.view_layer.update()\n    lowest = min((obj.matrix_world @ Vector(corner)).z for corner in obj.bound_box)\n    obj.location.z += floor_z - lowest\n    bpy.context.view_layer.update()\n\n\ndef place(obj: bpy.types.Object, x: float, y: float, yaw: float, floor_z: float) -> None:\n    \"\"\"Move the object to ``(x, y)``, turn it to ``yaw`` and stand it on the floor.\n\n    ``yaw`` is measured the Blender way: 0 rad points the model's front along\n    -Y, and positive yaw turns it counter-clockwise seen from above.\n    \"\"\"\n    obj.rotation_mode = \"XYZ\"\n    obj.rotation_euler = (0.0, 0.0, yaw)\n    obj.location.x = x\n    obj.location.y = y\n    drop_to_floor(obj, floor_z)\n\n\ndef face_towards(obj: bpy.types.Object, x: float, y: float,\n                 target_x: float, target_y: float, floor_z: float) -> None:\n    \"\"\"Stand the object at ``(x, y)`` turned to look at ``(target_x, target_y)``.\"\"\"\n    place(obj, x, y, yaw_facing(target_x - x, target_y - y), floor_z)\n", "pool_break.runtime_support": "\"\"\"Local runtime discovery; scripts also work in ordinary Python/Blender installs.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport os\nimport sys\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\n_dll_handles = []\nif os.name == \"nt\":\n    directory = Path(sys.prefix) / \"Library/bin\"\n    if directory.exists():\n        _dll_handles.append(os.add_dll_directory(str(directory)))\n\n\ndef python_for(role):\n    sys.path.insert(0, str(ROOT/'clean_scripts'))\n    from pcve_scene_runtime import python_for as resolve_python\n    return resolve_python(role)\n", "pool_break.scene_config": "\"\"\"Shared geometry and baseline parameters for the pool-break scene.\n\nBoth the PyBullet simulation and the Blender renderer import these constants, so\nthe collision bodies and the visible meshes cannot drift apart and the scene's\nthree exposed controls have exactly one definition.\n\nWorld conventions\n-----------------\n* The table's long axis is **X**. The cue ball breaks from ``+X`` towards\n  ``-X``, so the camera sits behind the cue at ``+X`` and looks down the table.\n* **+Y** is the far side of the table as seen from that camera's default rig\n  (forward ``-X``, up ``+Z`` => screen-right is ``+Y``), which is why a\n  positive ``cue_contact_offset`` reads as \"hit the right side of the apex\n  ball\" rather than as an abstract axis sign.\n* The felt surface is world ``z = 0``; every ball centre sits at ``z = radius``.\n  The imported table model is shifted down by its own felt height so the two\n  frames coincide -- see :func:`model_z_shift`.\n\nWhy the scene is scaled by the ball, not by the table\n-----------------------------------------------------\n``pool_table_animation.glb`` is authored in FBX centimetres: the felt mesh\nmeasures 1200.7 x 621.8 units and every ball mesh has a 18.93-unit radius. A\nreal 57.15 mm ball against that felt would make a 3.6 m table, so the model's\nballs are oversized relative to its cloth. Scaling so the *balls* are\nregulation (``SCENE_SCALE``) instead gives a 1.81 x 0.94 m playing surface --\na compact bar table, which is a real thing -- and keeps every number that the\nphysics cares about (ball/ball contact, cue speed, gravity) in familiar units.\nScaling by the table instead would leave 76 mm balls that visibly do not behave\nlike billiard balls at this camera distance.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nfrom pathlib import Path\n\n# ---------------------------------------------------------------- the model\n\nMODEL_PATH = _PCVE_ROOT / \"assets\" / \"models\" / \"pool_table_animation.glb\"\n\n# Measured off the model: every ball mesh is a sphere of this radius, the felt\n# mesh is a flat sheet at this height, and the cushion nose sits at the felt\n# edge (the vertex scan put it within 1.5 units of the felt bound).\nMODEL_BALL_RADIUS_UNITS = 18.9315\nMODEL_FELT_TOP_Z_UNITS = 100.012\nMODEL_PLAY_HALF_X_UNITS = 598.9\nMODEL_PLAY_HALF_Y_UNITS = 309.4\nMODEL_FLOOR_Z_UNITS = -363.94        # bottom of the legs, for the visual floor\n\n# Regulation pool ball: 57.15 mm diameter.\nBALL_RADIUS = 0.028575\nSCENE_SCALE = BALL_RADIUS / MODEL_BALL_RADIUS_UNITS\n\nPLAY_HALF_X = MODEL_PLAY_HALF_X_UNITS * SCENE_SCALE      # 0.904 m\nPLAY_HALF_Y = MODEL_PLAY_HALF_Y_UNITS * SCENE_SCALE      # 0.467 m\nMODEL_FLOOR_Z = MODEL_FLOOR_Z_UNITS * SCENE_SCALE\n\n\ndef model_z_shift() -> float:\n    \"\"\"How far to drop the imported table so its felt lands on world ``z = 0``.\"\"\"\n    return MODEL_FELT_TOP_Z_UNITS * SCENE_SCALE\n\n\n# Which mesh in the GLB plays which part. The file ships a full rack of\n# fifteen numbered balls plus a white cue ball and two cue sticks; the scene\n# only uses four of them and hides the rest, exactly the way\n# ``pool_collision`` hides the balls its shot does not use.\nCUE_BALL_MESH = \"Ball Clube_10 - Default_0\"\nAPEX_BALL_MESH = \"Ball1_01 - Default_0\"\nLEFT_BALL_MESH = \"Ball2_Material #158_0\"\nRIGHT_BALL_MESH = \"Ball3_Material #157_0\"\n# Hidden on import: the rest of the rack, and both sticks (this scene drives\n# the cue ball kinematically at frame 1 rather than animating a stick).\nUNUSED_BALL_PREFIX = \"Ball\"\nCUE_STICK_PREFIXES = (\"Cue stick\", \"Cue stick2\")\n\n# ----------------------------------------------------------------- the rack\n# The foot spot is the middle of the far half of the table, which is where a\n# rack is set in every published rule set.\nFOOT_SPOT_X = -PLAY_HALF_X / 2.0\n# Cue ball starts behind the head string and drives 1.05 m up the table.\nCUE_START_X = 0.60\n# A 0.5 mm air gap between the racked balls. Placing them exactly touching\n# makes Bullet resolve an initial overlap with a separation impulse on frame 1,\n# which pushes the rack apart before the cue ball has moved.\nRACK_GAP = 0.0005\n\n\ndef rack_centres() -> dict[str, tuple[float, float]]:\n    \"\"\"Where the three racked balls sit, in the table plane.\n\n    An equilateral triangle pointing at the cue ball: the apex on the foot\n    spot, the other two one centre-to-centre distance behind it. The apex is\n    therefore wedged between the two rear balls, which is what turns a cue-ball\n    impact into a break instead of into a single ball rolling away from an\n    untouched pair.\n\n    The rear pair sits at ``(-d * sqrt(3)/2, +/- d/2)`` relative to the apex --\n    half a spacing to either side, three quarters of a spacing back. That is the\n    first three balls of a real rack: the apex angle seen from the cue ball is\n    60 degrees, so each rear ball sits 30 degrees off the cue's line, and all\n    three pairs are one full spacing apart. Getting this the wrong way round\n    (rear pair at ``(-d/2, +/- d * sqrt(3)/2)``) still touches the apex but\n    leaves the two rear balls 1.73 spacings apart with a hole between them: a\n    flat 120-degree wedge that no rack has ever looked like, and the \"triangle\"\n    reads as two balls flanking a third from a distance.\n    \"\"\"\n    d = 2.0 * BALL_RADIUS + RACK_GAP\n    back = d * 0.8660254037844386\n    across = d * 0.5\n    return {\n        \"apex_ball\": (FOOT_SPOT_X, 0.0),\n        \"right_ball\": (FOOT_SPOT_X - back, +across),\n        \"left_ball\": (FOOT_SPOT_X - back, -across),\n    }\n\n\n# ---------------------------------------------------------------- physics\n\n# The three controls the benchmark exposes.\nBASELINE_PHYSICS = {\n    # A medium break: about 3.6 m/s of cue-ball speed. On a 1.8 m table this\n    # carries the cue ball 1.05 m to the rack in a quarter of a second and\n    # spreads the triangle to the cushions inside the clip.\n    \"cue_speed\": 3.6,            # m/s\n    # Signed lateral offset of the cue ball's line of travel from the apex\n    # ball's centre. + is the apex ball's right side (screen-right); +/-\n    # one ball radius is a half-ball hit, 2 radii is a clean miss.\n    #\n    # Deliberately not 0. A dead-centre hit is a stun shot: the cue ball comes\n    # straight back down its own line (+/-180 degrees) and the rack opens with\n    # perfect mirror symmetry, which no real break does and which makes the\n    # shot look like a diagram. 3 mm is 0.05 radii -- invisible at this camera\n    # distance -- but it is already enough to break the symmetry: the cue ball\n    # leaves at 157 degrees instead of coming straight back, and the apex ball\n    # is nudged to one side.\n    \"cue_contact_offset\": 0.003,  # m\n    \"cue_mass\": 0.17,            # kg -- regulation ball\n}\n\n# Everything an edit must NOT move, so a single-variable edit stays single.\nFIXED_PHYSICS = {\n    \"object_mass\": 0.17,\n    # Bullet multiplies the two bodies' coefficients, so the pair that matters\n    # is 0.25 * 0.12 = 0.03. This pair governs the *sliding* phase only -- it is\n    # what stops the cue ball skidding and gets it rolling, and it is kept low\n    # because at 0.6/0.9 the cue ball loses 5.3 m/s^2 and stops a third of the\n    # way to the rack. The loss that lasts, cloth drag, is ``BALL_ROLL_DECEL``.\n    \"ball_friction\": 0.25,\n    \"felt_friction\": 0.12,\n    # Left at zero on purpose. Bullet's rolling-friction constraint on a sphere\n    # does not give a rolling ball a constant drag -- it instead cancels the\n    # spin the contact friction is trying to build, so the ball slides the whole\n    # way at the full lateral coefficient. Cloth drag therefore lives in the\n    # lateral pair above, and the visible roll is reconstructed from each ball's\n    # path by ``simulate_pool_break.rolling_quaternions``.\n    \"ball_rolling_friction\": 0.0,\n    \"ball_spinning_friction\": 0.0,\n    \"ball_restitution\": 0.93,        # ball <-> ball reads 0.93 * 0.93 = 0.86\n    \"felt_restitution\": 0.10,\n    \"cushion_friction\": 0.30,\n    \"cushion_restitution\": 0.72,\n    \"gravity_z\": -9.81,\n}\n\n# Cloth drag, applied explicitly as a constant deceleration (m/s^2).\n#\n# Coulomb friction alone cannot stop a ball: once it rolls without slipping the\n# contact patch is stationary, the friction force drops to zero and a rigid\n# sphere on a rigid plane coasts forever. Real cloth dissipates through fibre\n# deformation and the ball's own hysteresis, which Bullet does not model, and\n# its ``rollingFriction`` term is not usable here (see above -- it fights the\n# spin instead of damping it). So the drag is integrated by hand, and without it\n# the clip ended with four balls still travelling at 0.5-1.2 m/s after five\n# cushion bounces, the triangle width oscillating between 70 mm and 570 mm from\n# frame to frame -- a pinball table, not a break.\n#\n# The value is the physical one. A ball rolling on worsted cloth decelerates at\n# 0.2-0.35 m/s^2 (rolling resistance coefficient 0.02-0.035); 0.30 is the fast\n# end of that band, which is what a brushed worsted cloth under a hard break\n# behaves like. Note that the total loss is not this number alone: while a ball\n# is still sliding it also pays the felt's Coulomb term (``ball_friction`` *\n# ``felt_friction`` * g = 0.29 m/s^2), so the hand-integrated drag is the\n# rolling-phase loss only.\n#\n# This used to be 0.8 to make a 2.5 s clip settle, and 0.8 is what a viewer\n# reads as wrong: it is 3x the real figure, and it stopped every ball by 1.9 s.\n# The constraint that forced it was clip length, and clip length is now 4 s\n# (``BASELINE_RENDER``), so the compromise is gone. At 0.30 the same break runs\n# 2.4 m of path per wing ball instead of 1.2 m -- a wing ball reaches the corner,\n# comes off the end cushion and carries back across the table -- and the last\n# ball dies at 3.96 s, one frame before the end.\n#\n# The two numbers are coupled: shortening the clip below ~3.8 s puts the\n# settling back in the cut-off, and at 2.5 s the two wing balls are still\n# running at 0.39 and 0.48 m/s when the clip ends.\nBALL_ROLL_DECEL = 0.30\n\n# Cushion nose height is 63.5 % of a ball diameter in every table spec.\nCUSHION_HEIGHT = 0.0363\nCUSHION_THICKNESS = 0.05\n# 96 substeps at 24 fps is a 0.43 ms step. The cue ball covers 1.5 mm per\n# substep at the default speed, which is the point: at 48 substeps a fast\n# contact resolves with about 3 mm of penetration on a 28.6 mm radius and the\n# rack visibly pops apart instead of being struck.\nSUBSTEPS_PER_FRAME = 96\n\n# ---------------------------------------------------------------- baseline\n\nBASELINE_RENDER = {\n    \"fps\": 24,\n    # Long enough for the break to finish on its own at the physical cloth\n    # drag: the last ball dies at 3.96 s. A 2.5 s clip (the old default) only\n    # fitted because ``BALL_ROLL_DECEL`` was inflated to stop everything early.\n    \"duration_sec\": 4.0,\n    # Same size every other rigid-body suite in this repo renders at.\n    \"resolution\": (960, 540),\n    \"samples\": 48,\n    \"camera_mode\": \"break\",\n}\n", "pool_break.table_model": "\"\"\"The hall's pool table, imported from its own model.\n\nWhy this exists\n---------------\nThe scene used to draw its table out of ``pool_table_animation.glb``, the same\nfile that supplies the four balls. That file is a low-poly game asset: the cloth\nis a single flat sheet, the rails are boxes with the corner pockets cut into\nthem by hand, and the apron is four boards. It was enough to hold the physics,\nbut at 1.5 m from the camera the cloth has no nap, the pockets have no throats\nand the frame has no joinery -- the table reads as a green tray with cushions.\n\nThis module brings in a proper billiard table (felt, cushions, leather pockets,\nturned legs, 4k maps) and fits it to the geometry the simulation already uses,\nso the ball trajectories stay valid. The physics is not touched: the balls are\nstill the meshes from ``pool_table_animation.glb`` and still keyed from the same\nPyBullet run. Only the table under them changes.\n\nFitting it to the simulation\n----------------------------\nEverything the shot cares about is measured off the imported mesh rather than\nguessed (see the ``MODEL_*`` constants, probed with vertical ray casts over the\ncloth):\n\n* the cloth plane -- the flat sheet the balls rest on -- sits at\n  ``MODEL_FELT_Z`` and is moved to world ``z = 0``, which is where the\n  simulation puts the felt and every ball centre;\n* the cushion noses -- the vertical faces a ball actually bounces off -- are at\n  ``+/- MODEL_NOSE_HALF_X`` and ``+/- MODEL_NOSE_HALF_Y``, so they are scaled\n  onto the simulation's cushion planes (``play_half_x`` / ``play_half_y``).\n\nThe two axes get **different** scale factors (0.922 and 0.943). That is not an\naccident: this model's playing surface is 1.96 x 0.99 m, the scene's is\n1.81 x 0.93 m, and those are not the same shape, because the scene was scaled so\nthat the *balls* are regulation rather than the table (see ``scene_config``).\nForcing one uniform factor would leave the cushions 5-10 mm off the planes the\nsimulation bounces the balls on -- close enough to look like the balls are\nsinking into the cushion at the moment of contact. A 2% anisotropy on a piece of\nfurniture is invisible; a ball 5 mm inside a cushion is not.\n\nWhat is dropped\n---------------\nThe file ships sixteen balls, a triangle rack, a chalk cube and two cue sticks\narranged on and around the table. None of them belong in this shot: the scene\nhas its own four balls under physics, and the rack would sit on the cue ball's\npath. They are hidden rather than deleted, the same way ``import_table`` hides\nthe fifteen balls the shot does not use.\n\nSource: https://sketchfab.com/3d-models/pool-table-billiard-table-with-cues-and-balls\n(Mark Peters, CC-BY-4.0)\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nfrom pathlib import Path\n\nimport bpy\n\nPOOL_TABLE_MODEL_PATH = (\n    _PCVE_ROOT\n    / \"assets\"\n    / \"models\"\n    / \"pool_table_-_billiard_table_with_cues_and_balls.glb\"\n)\n\n# ---------------------------------------------------------- measured off the file\n# Cloth plane. The most common vertex height in the bed mesh, and the height every\n# downward ray between the cushions returns -- the cloth is a single flat sheet.\nMODEL_FELT_Z = 0.795\n# Cushion noses, from ray casts across the cloth: the surface steps from the felt\n# up onto the cushion at exactly these distances from the table's centre.\nMODEL_NOSE_HALF_X = 0.980\nMODEL_NOSE_HALF_Y = 0.495\n\n# The two meshes that are the table. Everything else in the file is a prop.\nTABLE_MESH_SUFFIXES = {\n    \"_PoolTable_MTL_0\": \"pool_table_bed\",\n    \"_PoolTable_MTL_0.001\": \"pool_table_frame\",\n}\n\n\ndef _scale_for(play_half_x: float, play_half_y: float) -> tuple[float, float, float]:\n    \"\"\"Per-axis scale that lands this model's cushion noses on the scene's planes.\n\n    ``z`` takes the mean of the two so the cushions keep their profile: the\n    difference between the horizontal factors is 2%, and splitting it vertically\n    is less visible than picking one axis and squashing the cushion height.\n    \"\"\"\n    sx = play_half_x / MODEL_NOSE_HALF_X\n    sy = play_half_y / MODEL_NOSE_HALF_Y\n    return (sx, sy, (sx + sy) / 2.0)\n\n\n# The one material the table carries. Cloth, rails, apron and legs share it, and\n# it is one 4k atlas, so any adjustment has to be one that suits all of them.\nTABLE_MATERIAL = \"PoolTable_MTL\"\n\n# Grading, applied to the texture rather than baked into it.\n#\n# The atlas is a pale sage cloth. Under the hall's key lamp -- and through AgX,\n# which trades saturation for headroom as a value climbs -- a sample of the cloth\n# comes out (183, 206, 179): 23 levels between green and red is a mint, not a\n# felt. The wood is a grey-brown at similar brightness, so the table as a whole\n# reads as grey plastic while the room around it stays dark and warm.\n#\n# Saturation is the right operator here because it scales the colour that is\n# already there: the cloth gains most of it, the warm wood gains a little and\n# reads as varnished rather than painted, and anything neutral in the atlas\n# (sights, name plate) does not move at all. A multiply would have dragged the\n# wood green, and repainting the atlas is not this scene's business.\nGRADE_SATURATION = 1.55\nGRADE_VALUE = 0.88\n\n# Floor for the roughness the model ships.\n#\n# The frame is varnished and the map has it very smooth: under a 26 W bar lamp\n# 0.6 m above the cloth, the near rail returns two hard, pure-white patches of\n# reflected lamp where a real varnish would return a soft sheen. Clamping the\n# floor to 0.40 keeps the finish glossy -- the highlight is still there and still\n# moves with the camera -- but stops it clipping to white, and it costs the\n# cloth nothing: felt should be matte anyway, and its nap is in the normal map,\n# not in this channel.\nROUGHNESS_FLOOR = 0.40\n\n\ndef grade_table(table: list[bpy.types.Object]) -> None:\n    \"\"\"Grade the cloth's colour and the frame's finish, on the node tree.\n\n    Both go between the model's own maps and the Principled node, so the\n    original maps are untouched and each adjustment is one node to find.\n    \"\"\"\n    done: set[str] = set()\n    for obj in table:\n        for mat in obj.data.materials:\n            if mat is None or not mat.use_nodes or mat.name in done:\n                continue\n            done.add(mat.name)\n            tree = mat.node_tree\n            bsdf = next((n for n in tree.nodes if n.type == \"BSDF_PRINCIPLED\"), None)\n            if bsdf is None:\n                continue\n\n            base = bsdf.inputs[\"Base Color\"]\n            if base.is_linked:\n                source = base.links[0].from_node\n                grade = tree.nodes.new(\"ShaderNodeHueSaturation\")\n                grade.name = \"table_grade\"\n                grade.inputs[\"Saturation\"].default_value = GRADE_SATURATION\n                grade.inputs[\"Value\"].default_value = GRADE_VALUE\n                grade.location = (source.location.x + 220.0, source.location.y)\n                tree.links.new(source.outputs[\"Color\"], grade.inputs[\"Color\"])\n                tree.links.new(grade.outputs[\"Color\"], base)\n\n            rough = bsdf.inputs[\"Roughness\"]\n            if rough.is_linked:\n                link = rough.links[0]\n                clamp = tree.nodes.new(\"ShaderNodeMath\")\n                clamp.name = \"table_roughness_floor\"\n                clamp.operation = \"MAXIMUM\"\n                clamp.inputs[1].default_value = ROUGHNESS_FLOOR\n                clamp.location = (link.from_node.location.x + 220.0,\n                                  link.from_node.location.y - 220.0)\n                tree.links.new(link.from_socket, clamp.inputs[0])\n                tree.links.new(clamp.outputs[0], rough)\n\n\ndef import_table(play_half_x: float, play_half_y: float) -> list[bpy.types.Object]:\n    \"\"\"Import the table, fitted so its felt is world ``z = 0`` and its noses land\n    on ``+/- play_half_x`` / ``+/- play_half_y``.\n\n    Returns the two table meshes, each with its world transform baked into the\n    mesh data and the object left at the origin -- so nothing downstream has to\n    know about the empty hierarchy the file arrived in.\n    \"\"\"\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(POOL_TABLE_MODEL_PATH))\n    imported = [obj for obj in bpy.data.objects if obj not in before]\n\n    table: list[bpy.types.Object] = []\n    for obj in imported:\n        if obj.type != \"MESH\":\n            continue\n        renamed = next(\n            (name for suffix, name in TABLE_MESH_SUFFIXES.items()\n             if obj.name.endswith(suffix)),\n            None,\n        )\n        if renamed is None:\n            # Balls, the rack, the chalk and the cues.\n            obj.hide_viewport = True\n            obj.hide_render = True\n            continue\n        obj.name = renamed\n        table.append(obj)\n    if len(table) != len(TABLE_MESH_SUFFIXES):\n        raise RuntimeError(\n            f\"Expected {len(TABLE_MESH_SUFFIXES)} table meshes in \"\n            f\"{POOL_TABLE_MODEL_PATH.name}, found {len(table)}\"\n        )\n\n    # Drop the empties: the file nests the table under a centimetre-scaled root\n    # and a hundred-scaled group, and every one of those transforms has to end up\n    # in the mesh before the fitting scale can be written into ``obj.scale``.\n    for obj in table:\n        world = obj.matrix_world.copy()\n        obj.parent = None\n        obj.matrix_world = world\n    bpy.ops.object.select_all(action=\"DESELECT\")\n    for obj in table:\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active = table[0]\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n\n    scale = _scale_for(play_half_x, play_half_y)\n    for obj in table:\n        obj.scale = scale\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n\n    # The cloth is the one surface that has to be exact, so the drop is computed\n    # from the measured felt height rather than from the model's own floor.\n    for obj in table:\n        obj.location.z = -MODEL_FELT_Z * scale[2]\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=False)\n    bpy.ops.object.select_all(action=\"DESELECT\")\n\n    grade_table(table)\n    bpy.context.view_layer.update()\n    return table\n", "pool_break.wall_decor": "\"\"\"Wall pictures for the pool hall, from the cafe_wall_pictures pack.\n\nThe walls used to carry two prints built out of boxes: a brass frame, a card\nmount and a dark rectangle. At four metres that is a rectangle with a lighter\nrectangle inside it -- no glass, no print, no depth. They were placeholders\nthat had stopped pretending.\n\nThis pack ships three framed prints with proper 2k maps, glass, a moulded\nframe and a shadow gap behind. They cost one import.\n\nScale\n-----\nUnlike the props pack (which is a centimetre FBX that arrives at a tenth of\nits size), this one is authored in metres: each picture measures 488 x 335 x\n13 mm on import, which is a real cafe print and needs no correction factor.\nThe check is the thickness -- 13 mm is a picture frame, and 130 mm would not\nbe.\n\nThe three pictures sit on top of each other in the file\n-----------------------------------------------------\nAll three meshes share one origin and identical bounds: the pack is a set of\ninterchangeable frames, not a composed arrangement. So each one is unparented\nand treated as its own object, and the arrangement is decided here.\n\nSource: https://sketchfab.com/3d-models/cafe-wall-pictures-7016b8389cdc45658bb1399f476fad00\n(Guy in a Poncho, CC-BY-4.0)\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nfrom pathlib import Path\n\nimport bpy\n\nCAFE_MODEL_PATH = (\n    _PCVE_ROOT / \"assets\" / \"models\" / \"cafe_wall_pictures.glb\"\n)\n\nPICTURE_1 = \"wall_picture_1_wall_picture_1_2k_0\"\nPICTURE_2 = \"wall_picture_2_wall_picture_2_2k_0\"\nPICTURE_3 = \"wall_picture_3_wall_picture_3_0\"\n\nPICTURE_MESHES = (PICTURE_1, PICTURE_2, PICTURE_3)\n\n# The pack's three frames are not the same size, and one of them is a portrait:\n# PICTURE_1 is 488 x 335, PICTURE_2 is 428 x 623 (the portrait), PICTURE_3 is\n# 591 x 406 mm. At 0.88 they come out 429 x 295, 377 x 548 and 520 x 357 mm,\n# which is cafe-print size on a 4 m wall. The names do not sort by size -- the\n# portrait is PICTURE_2, not PICTURE_3 -- so check the numbers, not the index.\n#\n# The factor dates from the 25 mm rig, whose top of frame stopped at z = 0.77 m\n# above the felt: the portrait at 1:1 is 623 mm, and at any height clear of the\n# cap rail it broke the top edge. The current 21 mm rig sees up to z = 1.00 m, so\n# 1:1 would fit now -- the set is left at 0.88 because the arrangement was solved\n# against these sizes and nothing about the frame wants them bigger.\nPICTURE_SCALE = 0.88\n\n# The frame's moulding faces model +X and the print sits at the top of that\n# face, so a picture hung with no rotation looks at +X -- i.e. away from the\n# far wall and into the room, which is where the camera is.\nPICTURE_FRONT_AXIS = \"+X\"\n\n\ndef _flatten_alpha(materials) -> None:\n    \"\"\"Turn the pack's blended glass into dithered glass.\n\n    All three materials import with ``alphaMode: BLEND`` and an alpha channel\n    packed into the base texture. In EEVEE a blended surface has no depth\n    sorting of its own, so the glass pane and the print it covers resolve in\n    whatever order the triangles happen to be drawn in -- the prints came out\n    with large white and dark wedges sliced across them, which is what a\n    sorted-by-guess transparency looks like.\n\n    Stochastic alpha (``DITHERED``, which is ``HASHED`` in 4.x terms) keeps the\n    glass but resolves coverage per sample instead of per object, so there is\n    nothing left to sort. At four metres the dither noise is invisible; the\n    wedges were not.\n    \"\"\"\n    for mat in materials:\n        if mat is None:\n            continue\n        if hasattr(mat, \"surface_render_method\"):\n            mat.surface_render_method = \"DITHERED\"\n        if hasattr(mat, \"blend_method\"):\n            mat.blend_method = \"HASHED\"\n\n\ndef import_pictures() -> dict[str, bpy.types.Object]:\n    \"\"\"Import the pack and return its three prints, each standing on its own.\n\n    Every returned object is unparented, has its world transform baked into the\n    mesh data and its origin at the centre of its own bounds -- so hanging it\n    is ``location`` plus a yaw, with no inherited hierarchy to undo.\n    \"\"\"\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(CAFE_MODEL_PATH))\n    imported = [obj for obj in bpy.data.objects if obj not in before]\n\n    kept: dict[str, bpy.types.Object] = {}\n    materials = []\n    for obj in imported:\n        if obj.type != \"MESH\":\n            # The pack's Sketchfab/RootNode empties. They render nothing and\n            # keeping them parented would drag the prints along with them.\n            continue\n        world = obj.matrix_world.copy()\n        obj.parent = None\n        obj.matrix_world = world\n        bpy.ops.object.select_all(action=\"DESELECT\")\n        obj.select_set(True)\n        bpy.context.view_layer.objects.active = obj\n        bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n        obj.scale = (PICTURE_SCALE, PICTURE_SCALE, PICTURE_SCALE)\n        bpy.ops.object.transform_apply(scale=True)\n        bpy.ops.object.origin_set(type=\"ORIGIN_GEOMETRY\", center=\"BOUNDS\")\n        obj.select_set(False)\n        # glTF leaves objects in quaternion mode, where writing rotation_euler\n        # is silently ignored. Everything downstream yaws these objects.\n        obj.rotation_mode = \"XYZ\"\n        kept[obj.name] = obj\n        materials.extend(m for m in obj.data.materials if m is not None)\n    _flatten_alpha(materials)\n    bpy.context.view_layer.update()\n    return kept\n\n\ndef hang(obj: bpy.types.Object, x: float, y: float, z: float,\n         yaw: float = 0.0) -> None:\n    \"\"\"Hang one picture at ``(x, y, z)``, turned ``yaw`` about the vertical.\n\n    ``x`` is the centre of the frame; callers that want the back of the frame\n    against a wall should subtract half the thickness (``obj.dimensions.x``)\n    from the wall plane themselves, because only they know which wall it is.\n    \"\"\"\n    obj.rotation_mode = \"XYZ\"\n    obj.rotation_euler = (0.0, 0.0, yaw)\n    obj.location = (x, y, z)\n\n\ndef back_offset(obj: bpy.types.Object) -> float:\n    \"\"\"Half the frame's thickness, so it can be set back against a wall.\"\"\"\n    return obj.dimensions.x / 2.0\n", "pool_break": "\"\"\"Shared support modules for pool_break.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n"}""")

_BUNDLE_SCENE_ALIAS = 'pool_break'
_BUNDLE_ALIASES = ['cache_contract', 'props', 'runtime_support', 'scene_config', 'table_model', 'wall_decor', 'pool_break', 'pool_break.cache_contract', 'pool_break.props', 'pool_break.runtime_support', 'pool_break.scene_config', 'pool_break.table_model', 'pool_break.wall_decor']

class _SceneBundleLoader(_bundle_abc.MetaPathFinder, _bundle_abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _BUNDLE_SOURCES:
            return None
        package = (fullname == "scene_support" or fullname.count(".") == 1 and fullname.startswith("scene_support.") or fullname == _BUNDLE_SCENE_ALIAS)
        return _bundle_util.spec_from_loader(fullname, self, is_package=package)

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__spec__.name
        package = module.__spec__.submodule_search_locations is not None
        if name == "scene_support":
            origin = _BUNDLE_SCENE / "scene_support" / "__init__.py"
        elif name == _BUNDLE_SCENE_ALIAS:
            origin = _BUNDLE_SCENE / "scene_support" / name / "__init__.py"
        elif name.startswith(_BUNDLE_SCENE_ALIAS + "."):
            origin = _BUNDLE_SCENE / "scene_support" / name.replace(".", "/")
            origin = origin.with_suffix(".py")
        elif name.startswith("scene_support."):
            tail = name.split(".", 1)[1]
            if package:
                origin = _BUNDLE_SCENE / "scene_support" / tail / "__init__.py"
            else:
                origin = _BUNDLE_SCENE / "scene_support" / tail.replace(".", "/")
                origin = origin.with_suffix(".py")
        else:
            origin = _BUNDLE_SCRIPTS / (name + ".py")
        module.__file__ = str(origin)
        module.__package__ = name if package else (_BUNDLE_SCENE_ALIAS if name.startswith(_BUNDLE_SCENE_ALIAS + ".") or name in ['cache_contract', 'props', 'runtime_support', 'scene_config', 'table_model', 'wall_decor'] else name.rpartition("." )[0])
        if package:
            module.__path__ = [str(_BUNDLE_SCENE)] if name == _BUNDLE_SCENE_ALIAS else []
        source = _BUNDLE_SOURCES[name]
        exec(compile(source, str(origin), "exec"), module.__dict__)

def install_scene_support():
    if not any(isinstance(item, _SceneBundleLoader) for item in _bundle_sys.meta_path):
        _bundle_sys.meta_path.insert(0, _SceneBundleLoader())

install_scene_support()




